INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_nzl_fam', 'raghib_mufradat', 're_mfr_1263ddf00194dc2c', 'نزل',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 799,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"النُّزُولُ في الأصل: انحطاطٌ من عُلُوّ","en":"nuzul is, at root, a coming-down from a height","ur":"نزول کی اصل: بلندی سے نیچے اترنا"},"distinctive_note":{"ar":"يفصل الراغب بين الإنزال والتنزيل: التنزيل يختصّ بما نزل مفرَّقاً مرّةً بعد أخرى، والإنزال عامّ","en":"al-Raghib separates inzal from tanzil: tanzil is specific to what came down piecemeal, time after time, while inzal is the general term","ur":"الراغب انزال اور تنزیل میں فرق کرتے ہیں: تنزیل تھوڑا تھوڑا کر کے اترنے کے لیے خاص ہے، انزال عام ہے"},"authors_own_words":{"ar":"والفَرْقُ بين الإنزال والتنزيل أنّ التنزيل يختصّ بالموضع الذي يشير إليه إنزالُه مفرَّقاً ومرّةً بعد أخرى، والإنزالُ عامّ","en":"the difference between inzal and tanzil is that tanzil belongs to the place where its coming-down is piecemeal and repeated, while inzal is general","ur":"انزال و تنزیل کا فرق: تنزیل وہاں خاص ہے جہاں نزول متفرق اور بار بار ہو، انزال عام ہے"}},"poles":[{"key":"descent","label":{"ar":"الانحطاط من عُلُوّ","en":"coming down from a height","ur":"بلندی سے اترنا"}},{"key":"bestowal","label":{"ar":"إنزال النِّعَم والنِّقَم","en":"sending down favours and afflictions","ur":"نعمتوں اور عذابوں کا نازل کرنا"}},{"key":"hospitality","label":{"ar":"النُّزُل: ما يُعَدُّ للنازل","en":"nuzul: what is made ready for the one who alights","ur":"نُزُل: مہمان کے لیے تیار کیا گیا سامان"}}],"forms":[{"form_id":"mfr_nzl_f1","roman":"I","bab":"GT:form_family:bab_daraba","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"نَزَلَ","mudari":"يَنْزِلُ","masdar_term":"GT:derivation_type:masdar","masadir":["نُزُول"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"نازِل","ism_maf_term":null,"ism_maf":null,"pole":"descent","pole_family":"PF:nzl_descent_sending","trans":["GT:transitivity:intransitive"],"trans_note":null,"ayah":"al-Muminun 23:29","gloss":{"ar":"النزولُ الحسّيّ: الحطُّ عن عُلُوّ","en":"concrete nuzul: setting down from a height","ur":"حسی نزول: بلندی سے نیچے اتارنا"},"senses":[{"sense":{"ar":"الحطُّ عن عُلُوّ","en":"setting down from a height","ur":"بلندی سے اتر آنا"},"example":{"ar":"نَزَلَ عن دابَّته، ونَزَلَ في مكانِ كذا: حَطَّ رَحْلَهُ فيه","en":"he nazala from his mount; he nazala in such a place - he set his saddle down there","ur":"وہ سواری سے اترا، اور فلاں جگہ اترا: وہاں اپنا کجاوہ رکھا"}}],"shahid":{"ar":"رَبِّ أَنْزِلْنِي مُنْزَلًا مُبارَكاً وَأَنْتَ خَيْرُ الْمُنْزِلِينَ","en":"my Lord, land me at a blessed landing-place, for You are the best of those who bring to land","ur":"اے میرے رب! مجھے برکت والی جگہ اتار، اور تو بہترین اتارنے والا ہے"},"levels_with":[]},{"form_id":"mfr_nzl_f2","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:sound","madi":"أَنْزَلَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إنزال"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"مُنْزِل","ism_maf_term":null,"ism_maf":null,"pole":"bestowal","pole_family":"PF:nzl_descent_sending","trans":["GT:transitivity:ditransitive"],"trans_note":{"ar":"وإنّما خُصَّ لفظُ الإنزالِ في ﴿إِنَّا أَنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ﴾ لِما رُوِيَ أنّ القرآن نزل دفعةً واحدةً إلى سماء الدنيا، ثمّ نزل نجماً فنجماً","en":"the word inzal is used in \"We sent it down in a blessed night\" because of the report that the Quran came down all at once to the lowest heaven, then came down portion by portion","ur":"﴿إِنَّا أَنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ﴾ میں لفظِ انزال اسی روایت کی بنا پر ہے کہ قرآن یکبارگی آسمانِ دنیا پر اترا، پھر تھوڑا تھوڑا نازل ہوا"},"ayah":"al-Kahf 18:1; al-Hadid 57:25; ad-Dukhan 44:3","gloss":{"ar":"الإنزالُ عامٌّ، وهو أعمُّ من التنزيل","en":"inzal is the general term, wider than tanzil","ur":"انزال عام ہے، اور تنزیل سے وسیع تر ہے"},"senses":[{"sense":{"ar":"إنزالُ الشيء نفسِه","en":"sending down the thing itself","ur":"خود اُس چیز کا نازل کرنا"},"example":{"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلى عَبْدِهِ الْكِتابَ","en":"praise be to God who sent down upon His servant the Book","ur":"سب تعریف اللہ کے لیے جس نے اپنے بندے پر کتاب اتاری"}},{"sense":{"ar":"إنزالُ أسبابِه والهدايةُ إليه","en":"sending down its means, and guidance to it","ur":"اُس کے اسباب کا نازل کرنا اور اُس کی طرف ہدایت"},"example":{"ar":"وَأَنْزَلْنَا الْحَدِيدَ","en":"and We sent down iron","ur":"اور ہم نے لوہا اتارا"}}],"shahid":{"ar":"إِنَّا أَنْزَلْناهُ فِي لَيْلَةٍ مُبارَكَةٍ","en":"We sent it down in a blessed night","ur":"ہم نے اسے ایک بابرکت رات میں اتارا"},"levels_with":[]},{"form_id":"mfr_nzl_f3","roman":"II","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_ii","root_type":"GT:root_type:sound","madi":"نَزَّلَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["تنزيل"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"bestowal","pole_family":"PF:nzl_descent_sending","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":"al-Isra 17:106; al-Hijr 15:9","gloss":{"ar":"التنزيلُ يختصّ بالمفرَّقِ مرّةً بعد أخرى","en":"tanzil is specific to what comes piecemeal, time after time","ur":"تنزیل تھوڑا تھوڑا کر کے بار بار اترنے کے لیے خاص ہے"},"senses":[{"sense":{"ar":"إنزالٌ مفرَّقٌ مرّةً بعد أخرى","en":"a sending-down in portions, time after time","ur":"متفرق طور پر بار بار اتارنا"},"example":{"ar":"وَنَزَّلْناهُ تَنْزِيلًا","en":"and We sent it down a sending-down","ur":"اور ہم نے اسے تدریجاً اتارا"}}],"shahid":{"ar":"إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ","en":"it is We who sent down the Reminder","ur":"بےشک ہم ہی نے ذکر نازل کیا"},"levels_with":[]},{"form_id":"mfr_nzl_f4","roman":"V","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_v","root_type":"GT:root_type:sound","madi":"تَنَزَّلَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["تنزُّل"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"descent","pole_family":"PF:nzl_descent_sending","trans":["GT:transitivity:intransitive"],"trans_note":null,"ayah":"al-Qadr 97:4; al-Shuara 26:210; al-Talaq 65:12","gloss":{"ar":"التنزُّلُ كالنزولِ به، ولا يقال: نَزَلَ اللهُ بكذا ولا تنزَّل","en":"tanazzul is like coming down with a thing; but one does not say God nazala or tanazzala with something","ur":"تنزّل: کسی چیز کے ساتھ اترنا؛ اللہ کے لیے یہ نہیں کہا جاتا"},"senses":[{"sense":{"ar":"نزولُ الملائكةِ بالأمر","en":"the angels coming down with the command","ur":"فرشتوں کا حکم لے کر اترنا"},"example":{"ar":"تَنَزَّلُ الْمَلائِكَةُ","en":"the angels come down","ur":"فرشتے اترتے ہیں"}},{"sense":{"ar":"وما كان من الشيطان فلا يقال فيه إلّا التنزُّل","en":"of what comes from Satan, only tanazzul is said","ur":"شیطان کی طرف سے جو ہو اُس کے لیے صرف تنزّل کہا جاتا ہے"},"example":{"ar":"وَما تَنَزَّلَتْ بِهِ الشَّياطِينُ","en":"the satans did not bring it down","ur":"اسے شیاطین لے کر نہیں اترے"}}],"shahid":{"ar":"يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَّ","en":"the command descends among them","ur":"اُن کے درمیان حکم اترتا رہتا ہے"},"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.799. The inzal/tanzil contrast is the article''s spine and is a distinction, not an equivalence, so no levels_with is asserted. al-Nuzul (provision for the one who alights) is a further pole he treats but is left to the passage layer. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_layl_fam', 'raghib_mufradat', 're_mfr_68ee573be494c07f', 'ليل',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 751,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:hollow_y","block_meta":{"core":{"ar":"لَيْلٌ ولَيْلَةٌ، وجمعُها: لَيالٍ ولَيائِلُ ولَيْلاتٌ","en":"layl and layla, plural: layalin, layail, laylat","ur":"لیل اور لیلہ، جمع: لیالی، لیائل، لیلات"},"distinctive_note":{"ar":"مدخلُ الراغب في ليل صرفيٌّ محض: بناءُ الكلمة وجموعُها وتصغيرُها، ثمّ الشواهد؛ ولا يُعطي فيه فعلاً","en":"al-Raghib''s entry on layl is purely morphological - the word''s build, plurals and diminutive, then the citations; he gives no verb for it","ur":"الراغب کا مدخلِ لیل خالص صرفی ہے: بناوٹ، جمع، تصغیر، پھر شواہد؛ کوئی فعل نہیں دیتے"},"authors_own_words":{"ar":"وقيل: أصلُ ليلةٍ لَيْلاةٌ، بدليلِ تصغيرِها على لُيَيْلةٍ، وجمعِها على ليالٍ","en":"it is said the origin of layla is laylah, on the evidence of its diminutive luyayla and its plural layalin","ur":"کہا گیا کہ لیلہ کی اصل لَیْلاۃ ہے، اس کی تصغیر لُیَیْلہ اور جمع لیالی اس پر دلیل ہے"}},"poles":[{"key":"night","label":{"ar":"الليلُ المقابلُ للنهار","en":"night, the counterpart of day","ur":"رات، جو دن کے مقابل ہے"}}],"forms":[{"form_id":"mfr_layl_f1","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hollow_y","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"night","pole_family":"PF:layl_night","trans":[],"trans_note":{"ar":"وقيل: لَيْلٌ أَلْيَلُ، وليلةٌ لَيْلاءُ","en":"and it is said: laylun alyal, and laylatun layla - an intensified night","ur":"کہا جاتا ہے: لَیْلٌ أَلْیَل، اور لَیْلَۃٌ لَیْلاء"},"ayah":"Ibrahim 14:33; al-Qadr 97:1; ad-Dukhan 44:3","gloss":{"ar":"لَيْلٌ ولَيْلَةٌ، والجمعُ: لَيالٍ ولَيائِلُ ولَيْلاتٌ","en":"layl and layla; the plurals are layalin, layail and laylat","ur":"لیل و لیلہ؛ جمع: لیالی، لیائل، لیلات"},"senses":[{"sense":{"ar":"الليلُ واحدتُه ليلة","en":"layl, whose singular unit is layla","ur":"لیل، جس کا واحد لیلہ ہے"},"example":{"ar":"وَسَخَّرَ لَكُمُ اللَّيْلَ وَالنَّهارَ","en":"and He made the night and the day subservient to you","ur":"اور اُس نے رات اور دن کو تمہارے لیے مسخر کیا"}}],"shahid":{"ar":"إِنَّا أَنْزَلْناهُ فِي لَيْلَةِ الْقَدْرِ","en":"We sent it down in the Night of Decree","ur":"ہم نے اسے شبِ قدر میں اتارا"},"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.751. Genuinely a one-row family: al-Raghib gives no verb under layl, only the noun''s morphology and its Quranic citations, so the single row carries form_tier noun_derivatives rather than a fabricated bab. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_ndhr_fam', 'raghib_mufradat', 're_mfr_608a3fa50813c747', 'نذر',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 797,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"النَّذْرُ: أن تُوجِبَ على نفسِك ما ليس بواجبٍ لحدوثِ أمر","en":"nadhr is to bind upon yourself what is not obligatory, on account of something that has happened","ur":"نذر: کسی امر کے پیش آنے پر غیر واجب کو اپنے اوپر واجب کر لینا"},"distinctive_note":{"ar":"يقابل الراغب الإنذارَ بالتبشير: هذا إخبارٌ فيه تخويف، وذاك إخبارٌ فيه سرور","en":"al-Raghib sets indhar opposite tabshir: one is an announcement carrying fear, the other an announcement carrying joy","ur":"الراغب انذار کو تبشیر کے مقابل رکھتے ہیں: ایک خبر میں خوف ہے، دوسری میں خوشی"},"authors_own_words":{"ar":"والإنذارُ: إخبارٌ فيه تخويف، كما أنّ التبشيرَ إخبارٌ فيه سرور","en":"indhar is an announcement carrying fear, just as tabshir is an announcement carrying joy","ur":"انذار: وہ خبر جس میں ڈر ہو، جیسے تبشیر وہ خبر جس میں خوشی ہو"}},"poles":[{"key":"vow","label":{"ar":"إيجابُ ما ليس بواجب","en":"binding what is not obligatory","ur":"غیر واجب کو واجب کرنا"}},{"key":"warning","label":{"ar":"الإخبارُ الذي فيه تخويف","en":"announcement carrying fear","ur":"وہ خبر جس میں تخویف ہو"}},{"key":"heeding","label":{"ar":"العلمُ بالشيء والحذرُ منه","en":"knowing a thing and taking care against it","ur":"جان لینا اور بچ رہنا"}}],"forms":[{"form_id":"mfr_ndhr_f1","roman":"I","bab":"GT:form_family:bab_daraba","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"نَذَرَ","mudari":"يَنْذِرُ","masdar_term":"GT:derivation_type:masdar","masadir":["نَذْر"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"vow","pole_family":"PF:ndhr_vow_warning","trans":["GT:transitivity:transitive_by_harf"],"trans_note":null,"ayah":"Maryam 19:26; al-Baqara 2:270","gloss":{"ar":"نَذَرْتُ للهِ أمراً: أوجبتُه على نفسي","en":"I nadhartu a thing to God - I bound it upon myself","ur":"میں نے اللہ کے لیے نذر مانی: اُسے اپنے اوپر لازم کیا"},"senses":[{"sense":{"ar":"إيجابُ ما ليس بواجبٍ على النفس لحدوثِ أمر","en":"binding upon oneself what is not obligatory, on account of something that has happened","ur":"کسی امر کے سبب غیر واجب کو اپنے اوپر لازم کرنا"},"example":{"ar":"إِنِّي نَذَرْتُ لِلرَّحْمنِ صَوْماً","en":"I have vowed a fast to the Merciful","ur":"میں نے رحمن کے لیے روزے کی نذر مانی ہے"}}],"shahid":{"ar":"وَما أَنْفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ","en":"whatever you spend or whatever vow you vow","ur":"اور جو خرچ تم کرو یا جو نذر تم مانو"},"levels_with":[]},{"form_id":"mfr_ndhr_f2","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:sound","madi":"أَنْذَرَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إنذار"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"مُنْذِر","ism_maf_term":null,"ism_maf":null,"pole":"warning","pole_family":"PF:ndhr_vow_warning","trans":["GT:transitivity:ditransitive"],"trans_note":null,"ayah":"al-Layl 92:14; Fussilat 41:13; Ya Sin 36:6","gloss":{"ar":"الإنذارُ: إخبارٌ فيه تخويف","en":"indhar: an announcement carrying fear","ur":"انذار: وہ خبر جس میں تخویف ہو"},"senses":[{"sense":{"ar":"التخويفُ بالإخبار","en":"giving fear by announcing","ur":"خبر دے کر ڈرانا"},"example":{"ar":"فَأَنْذَرْتُكُمْ ناراً تَلَظَّى","en":"so I have warned you of a blazing fire","ur":"سو میں نے تمہیں بھڑکتی آگ سے ڈرایا"}}],"shahid":{"ar":"لِتُنْذِرَ قَوْماً ما أُنْذِرَ آباؤُهُمْ","en":"that you may warn a people whose fathers were not warned","ur":"تاکہ تم اُس قوم کو ڈراؤ جن کے باپ دادا نہ ڈرائے گئے"},"levels_with":[]},{"form_id":"mfr_ndhr_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"warning","pole_family":"PF:ndhr_vow_warning","trans":[],"trans_note":null,"ayah":"Nuh 71:2; al-Najm 53:56; al-Qamar 54:23","gloss":{"ar":"النَّذيرُ: المُنذِر، ويقع على كلِّ شيءٍ فيه إنذار، إنساناً كان أو غيره","en":"al-nadhir is the warner, and applies to anything that carries warning, human or otherwise","ur":"نذیر: ڈرانے والا، اور ہر اُس چیز پر بولا جاتا ہے جس میں انذار ہو، انسان ہو یا کوئی اور"},"senses":[{"sense":{"ar":"المُنذِر مطلقاً","en":"the warner, unqualified","ur":"مطلق ڈرانے والا"},"example":{"ar":"إِنِّي لَكُمْ نَذِيرٌ مُبِينٌ","en":"I am to you a clear warner","ur":"میں تمہارے لیے کھلا ڈرانے والا ہوں"}},{"sense":{"ar":"والنُّذُرُ جمعُه","en":"and al-nudhur is its plural","ur":"اور نُذُر اس کی جمع ہے"},"example":{"ar":"هذا نَذِيرٌ مِنَ النُّذُرِ الْأُولى","en":"this is a warner of the same kind as the earlier warners","ur":"یہ پہلے ڈرانے والوں میں سے ایک ڈرانے والا ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_ndhr_f4","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"نَذِرَ","mudari":"يَنْذَرُ","masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"heeding","pole_family":"PF:ndhr_vow_warning","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":null,"gloss":{"ar":"نَذِرْتُ بالشيء: علمتُه وحذِرتُه","en":"nadhirtu of a thing - I came to know it and took care against it","ur":"نَذِرْتُ: میں نے جان لیا اور بچ رہا"},"senses":[],"shahid":{"ar":"وقد نَذِرْتُ، أي: عَلِمْتُ ذلك وحَذِرْتُ","en":"and I have nadhirtu - that is, I knew it and was on guard","ur":"اور میں نے نَذِرْتُ کیا، یعنی: جان لیا اور محتاط ہو گیا"},"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.797. Three distinct poles in one short article: the vow (Form I bab daraba), the warning (Form IV and the nadhir/nudhur nominals), and the rarely-noticed nadhira of bab samia meaning to know-and-beware. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
