VALUES ('blk_mfr_frq_fam', 'raghib_mufradat', 're_mfr_006c714331060fc5', 'فرق',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 632,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"الفَرْقُ يقارب الفَلْق، لكنّ الفَلْقَ اعتباراً بالانشقاق، والفَرْقَ اعتباراً بالانفصال","en":"farq is near to falq, but falq is considered with respect to splitting, farq with respect to separation","ur":"فرق فلق کے قریب ہے، مگر فلق شق ہونے کے اعتبار سے اور فرق جدا ہونے کے اعتبار سے"},"distinctive_note":{"ar":"يرتّب الراغب الجذرَ في ثلاث: الفصلُ الحسّيّ والعقليّ، والخوفُ الذي يصدع القلب، والفُرقانُ الذي هو أبلغُ من الفَرْق","en":"al-Raghib orders the root in three: separation whether seen by eye or by insight, the fear that cracks the heart, and al-furqan which is stronger than farq","ur":"الراغب جذر کو تین میں مرتب کرتے ہیں: حسی و عقلی فصل، دل کو چیر دینے والا خوف، اور فرقان جو فرق سے ابلغ ہے"},"authors_own_words":{"ar":"والفُرقانُ أبلغُ من الفَرْق، لأنه يُستعمل في الفرق بين الحقّ والباطل، وهو اسمٌ لا مصدرٌ فيما قيل","en":"al-furqan is stronger than farq, because it is used of the distinction between truth and falsehood, and it is a noun, not a verbal noun, as has been said","ur":"فرقان فرق سے ابلغ ہے، کیونکہ یہ حق و باطل کے فرق میں استعمال ہوتا ہے، اور یہ اسم ہے، مصدر نہیں"}},"poles":[{"key":"separation","label":{"ar":"الفصلُ بين الشيئين","en":"setting two things apart","ur":"دو چیزوں کے درمیان فصل"}},{"key":"fear","label":{"ar":"تفرُّقُ القلبِ من الخوف","en":"the heart coming apart from fear","ur":"خوف سے دل کا پھٹ جانا"}},{"key":"criterion","label":{"ar":"الفَرْقُ بين الحقِّ والباطل","en":"the distinction between truth and falsehood","ur":"حق و باطل کے درمیان فرق"}}],"forms":[{"form_id":"mfr_frq_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"فَرَقَ","mudari":"يَفْرُقُ","masdar_term":"GT:derivation_type:masdar","masadir":["فَرْق"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"فارِق","ism_maf_term":null,"ism_maf":null,"pole":"separation","pole_family":"PF:frq_separation_criterion","trans":["GT:transitivity:transitive_by_harf"],"trans_note":{"ar":"وعلى هذا: فَالْفارِقاتِ فَرْقاً، يعني الملائكةَ الذين يفصلون بين الأشياء حسبما أمرهم الله","en":"and on this: \"those that separate by a separating\" means the angels who set things apart as God has ordered them","ur":"اسی پر: ﴿فَالْفارِقاتِ فَرْقاً﴾ یعنی وہ فرشتے جو اللہ کے حکم کے مطابق چیزوں میں فصل کرتے ہیں"},"ayah":"al-Baqara 2:50; al-Maida 5:25; ad-Dukhan 44:4","gloss":{"ar":"فَرَقْتُ بين الشيئين: فصلتُ بينهما","en":"faraqtu between two things - I set them apart","ur":"میں نے دو چیزوں کے درمیان فصل کیا"},"senses":[{"sense":{"ar":"الفصلُ بفصلٍ يدركه البصرُ أو تدركه البصيرة","en":"a separating that the eye may perceive, or that insight perceives","ur":"ایسا فصل جسے آنکھ دیکھے یا بصیرت پائے"},"example":{"ar":"فَافْرُقْ بَيْنَنا وَبَيْنَ الْقَوْمِ الْفاسِقِينَ","en":"so separate us from the transgressing people","ur":"پس ہمارے اور نافرمان قوم کے درمیان جدائی کر دے"}}],"shahid":{"ar":"فِيها يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ","en":"in it every wise matter is set apart","ur":"اُسی رات ہر حکمت والا امر الگ کر دیا جاتا ہے"},"levels_with":[]},{"form_id":"mfr_frq_f2","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"فَرِقَ","mudari":"يَفْرَقُ","masdar_term":"GT:derivation_type:masdar","masadir":["فَرَق"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"fear","pole_family":"PF:frq_separation_criterion","trans":["GT:transitivity:intransitive"],"trans_note":{"ar":"واستعمالُ الفَرَقِ فيه كاستعمال الصَّدْعِ والشَّقِّ فيه","en":"the use of faraq for it is like the use of sadi and shaqq for it","ur":"اس میں فَرَق کا استعمال ویسا ہی ہے جیسے صدع اور شق کا"},"ayah":"al-Tawba 9:56","gloss":{"ar":"الفَرَقُ: تفرُّقُ القلبِ من الخوف","en":"al-faraq: the heart coming apart from fear","ur":"فَرَق: خوف سے دل کا منتشر ہو جانا"},"senses":[{"sense":{"ar":"الخوفُ الذي يصدعُ القلب","en":"the fear that cracks the heart","ur":"وہ خوف جو دل کو چیر دے"},"example":{"ar":"وَلكِنَّهُمْ قَوْمٌ يَفْرَقُونَ","en":"but they are a people who take fright","ur":"لیکن وہ ایسے لوگ ہیں جو ڈرتے ہیں"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_frq_f3","roman":"II","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_ii","root_type":"GT:root_type:sound","madi":"فَرَّقَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["تفريق"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"separation","pole_family":"PF:frq_separation_criterion","trans":["GT:transitivity:transitive_by_harf"],"trans_note":null,"ayah":"al-Baqara 2:102; al-Anam 6:159","gloss":{"ar":"التفريقُ أصلُه للتكثير، ويقال في تشتيتِ الشملِ والكلمة","en":"tafriq is at root for multiplicity, and is said of scattering a company and a common word","ur":"تفریق کی اصل تکثیر ہے، اور یہ جمعیت و کلمہ کے منتشر کرنے میں بولا جاتا ہے"},"senses":[{"sense":{"ar":"تشتيتُ الشملِ والكلمة","en":"scattering the company and the common word","ur":"جمعیت اور کلمے کو منتشر کرنا"},"example":{"ar":"يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ","en":"by which they separate a man and his wife","ur":"جس سے وہ مرد اور اُس کی بیوی میں جدائی ڈالتے ہیں"}}],"shahid":{"ar":"إِنَّ الَّذِينَ فَرَّقُوا دِينَهُمْ","en":"those who have divided their religion","ur":"بےشک جنہوں نے اپنے دین کو ٹکڑے کر دیا"},"levels_with":[]},{"form_id":"mfr_frq_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"criterion","pole_family":"PF:frq_separation_criterion","trans":[],"trans_note":null,"ayah":"al-Anfal 8:29; al-Anfal 8:41; al-Baqara 2:53; al-Furqan 25:1","gloss":{"ar":"الفُرقانُ اسمٌ لا مصدر، وهو أبلغُ من الفَرْق","en":"al-furqan is a noun, not a verbal noun, and is stronger than farq","ur":"فرقان اسم ہے، مصدر نہیں، اور فرق سے ابلغ ہے"},"senses":[{"sense":{"ar":"اليومُ الذي يُفرَق فيه بين الحقِّ والباطل","en":"the day on which truth and falsehood are set apart","ur":"وہ دن جس میں حق و باطل الگ کیے جائیں"},"example":{"ar":"يَوْمَ الْفُرْقانِ","en":"the day of the criterion","ur":"فیصلے کا دن"}},{"sense":{"ar":"كلامُ الله، لفرقِه بين الحقِّ والباطل في الاعتقاد، والصدقِ والكذبِ في المقال، والصالحِ والطالحِ في الأعمال","en":"the speech of God, for its separating truth from falsehood in belief, truth from lie in speech, and sound from corrupt in deeds","ur":"اللہ کا کلام، کیونکہ وہ اعتقاد میں حق و باطل، قول میں صدق و کذب، اور عمل میں صالح و فاسد کے درمیان فرق کرتا ہے"},"example":{"ar":"تَبارَكَ الَّذِي نَزَّلَ الْفُرْقانَ","en":"blessed is He who sent down the Criterion","ur":"بابرکت ہے وہ جس نے فرقان نازل کیا"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.632. The two Form I rows are al-Raghib''s own split, not an editorial one: faraqa/yafruqu of separating and fariqa/yafraqu of fear are different babs with different masadir. He also reports the reading faraqnahu (we made it plain) against farraqnahu (we sent it down piecemeal); that variant belongs to the passage layer. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
