VALUES ('blk_mfr_amr_fam', 'raghib_mufradat', 're_mfr_907537859a8652c6', 'امر',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 88,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:hamzated","block_meta":{"core":{"ar":"الأَمْرُ: الشأنُ، وجمعُه أُمور؛ ومصدرُ أمرتُه: إذا كلَّفتَه أن يفعل شيئاً","en":"al-amr is the affair, plural umur; and it is the verbal noun of amartuhu - when you charge someone to do a thing","ur":"الأمر: شان، جمع امور؛ اور امرتہ کا مصدر: جب تم کسی کو کوئی کام کرنے کا مکلف بناؤ"},"distinctive_note":{"ar":"يفرد الراغب للأمرِ بمعنى الإبداعِ بابًا يختصّ بالله دون الخلائق، ويحمل عليه: قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي","en":"al-Raghib singles out amr in the sense of origination as belonging to God and not to creatures, and reads \"say: the spirit is of my Lord''s amr\" upon it","ur":"الراغب امر بمعنی ابداع کو اللہ کے ساتھ خاص کرتے ہیں، اور ﴿قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّي﴾ کو اسی پر محمول کرتے ہیں"},"authors_own_words":{"ar":"ويقال للإبداع: أمرٌ، ويختصّ ذلك بالله تعالى دون الخلائق","en":"origination is called amr, and that belongs to God alone, not to creatures","ur":"ابداع کو امر کہا جاتا ہے، اور یہ اللہ کے ساتھ خاص ہے، مخلوق کے ساتھ نہیں"}},"poles":[{"key":"command","label":{"ar":"التقدُّمُ بالشيء","en":"putting a thing forward as an order","ur":"کسی چیز کا حکم دینا"}},{"key":"affair","label":{"ar":"الشأنُ الجامعُ للأقوالِ والأفعال","en":"the affair, covering all sayings and doings","ur":"شان، جو تمام اقوال و افعال کو شامل ہے"}},{"key":"origination","label":{"ar":"الإبداعُ المختصُّ بالله","en":"origination, proper to God alone","ur":"ابداع، جو اللہ کے ساتھ خاص ہے"}},{"key":"abundance","label":{"ar":"الكثرةُ وكِبَرُ الأمر","en":"multiplying, a matter growing great","ur":"کثرت اور امر کا بڑھ جانا"}}],"forms":[{"form_id":"mfr_amr_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:hamzated","madi":"أَمَرَ","mudari":"يَأْمُرُ","masdar_term":"GT:derivation_type:masdar","masadir":["أَمْر"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"آمِر","ism_maf_term":null,"ism_maf":null,"pole":"command","pole_family":"PF:amr_command_affair","trans":["GT:transitivity:ditransitive"],"trans_note":null,"ayah":"al-Saffat 37:102; al-Baqara 2:228","gloss":{"ar":"أمرتُه: كلَّفتُه أن يفعل شيئاً","en":"amartuhu - I charged him to do a thing","ur":"میں نے اُسے حکم دیا: کسی کام کا مکلف بنایا"},"senses":[{"sense":{"ar":"التقدُّمُ بالشيء، سواءٌ كان بقولهم: افعلْ وليفعلْ، أو بلفظِ خبرٍ، أو بإشارةٍ أو غير ذلك","en":"putting a thing forward, whether by saying do and let him do, or in the words of a statement, or by a sign, or otherwise","ur":"کسی چیز کو آگے رکھنا: خواہ افعل و لیفعل سے ہو، یا خبر کے لفظ سے، یا اشارے سے، یا کسی اور طرح"},"example":{"ar":"يا أَبَتِ افْعَلْ ما تُؤْمَرُ","en":"my father, do what you are commanded","ur":"اے میرے باپ! جو آپ کو حکم دیا جا رہا ہے کر گزریے"}}],"shahid":{"ar":"ألا ترى أنّه سمّى ما رأى إبراهيمُ في المنامِ من ذبحِ ابنِه أمراً","en":"do you not see that he called what Abraham saw in sleep, the sacrificing of his son, an amr","ur":"کیا تم نہیں دیکھتے کہ ابراہیم نے خواب میں بیٹے کے ذبح کا جو منظر دیکھا اُسے امر کہا گیا"},"levels_with":[]},{"form_id":"mfr_amr_f2","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hamzated","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"affair","pole_family":"PF:amr_command_affair","trans":[],"trans_note":{"ar":"وقوله: أَتى أَمْرُ اللَّهِ، إشارةٌ إلى القيامة، فذكره بأعمِّ الألفاظ","en":"and \"the amr of God has come\" points to the Resurrection, so he named it with the most general of words","ur":"﴿أَتى أَمْرُ اللَّهِ﴾ قیامت کی طرف اشارہ ہے، اسی لیے عام ترین لفظ سے ذکر کیا"},"ayah":"Hud 11:123; Al Imran 3:154; Hud 11:97","gloss":{"ar":"الأَمْرُ: الشأنُ، وهو لفظٌ عامٌّ للأفعالِ والأقوالِ كلِّها","en":"al-amr is the affair - a term general to all deeds and sayings","ur":"الأمر: شان، اور یہ تمام افعال و اقوال کے لیے عام لفظ ہے"},"senses":[{"sense":{"ar":"الشأنُ الجامع","en":"the encompassing affair","ur":"جامع شان"},"example":{"ar":"إِلَيْهِ يُرْجَعُ الْأَمْرُ كُلُّهُ","en":"to Him the whole affair is returned","ur":"اُسی کی طرف سارا معاملہ لوٹایا جاتا ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_amr_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hamzated","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"origination","pole_family":"PF:amr_command_affair","trans":[],"trans_note":null,"ayah":"al-Araf 7:54; al-Isra 17:85; al-Qamar 54:50; Fussilat 41:12","gloss":{"ar":"الأمرُ بمعنى الإبداع، ويختصّ بالله دون الخلائق","en":"amr in the sense of origination, proper to God and not to creatures","ur":"امر بمعنی ابداع، جو اللہ کے ساتھ خاص ہے"},"senses":[{"sense":{"ar":"الإبداع","en":"origination","ur":"ابداع"},"example":{"ar":"أَلا لَهُ الْخَلْقُ وَالْأَمْرُ","en":"His indeed are the creating and the amr","ur":"خبردار! اُسی کے لیے خلق اور امر ہے"}},{"sense":{"ar":"سرعةُ الإيجاد، عُبِّر عنها بأسرعِ ما يدركه وهمُنا","en":"the swiftness of bringing-into-being, expressed by the swiftest thing our imagining can grasp","ur":"ایجاد کی سرعت، جسے ہمارے وہم کی تیز ترین چیز سے تعبیر کیا گیا"},"example":{"ar":"وَما أَمْرُنا إِلَّا واحِدَةٌ","en":"and Our amr is but one","ur":"اور ہمارا امر تو بس ایک ہی بات ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_amr_f4","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:hamzated","madi":"أَمِرَ","mudari":"يَأْمَرُ","masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"abundance","pole_family":"PF:amr_command_affair","trans":["GT:transitivity:intransitive"],"trans_note":{"ar":"وذلك لأنّ القومَ إذا كثُروا صاروا ذا أميرٍ، إذ لا بدَّ لهم من سائسٍ يسوسُهم","en":"and that is because when a people grow many they come to have a commander, since they must have someone to govern them","ur":"کیونکہ جب قوم بڑھ جائے تو اُس کا امیر ہوتا ہے، اِس لیے کہ اُنہیں کوئی نظم دینے والا چاہیے"},"ayah":"al-Kahf 18:71","gloss":{"ar":"أَمِرَ القومُ: كثُروا؛ وأَمِرَ الأمرُ: كَبُرَ وكَثُرَ","en":"amira the people - they grew many; amira the matter - it grew great and abundant","ur":"أَمِرَ القوم: وہ بڑھ گئے؛ أَمِرَ الأمر: معاملہ بڑا اور زیادہ ہو گیا"},"senses":[],"shahid":{"ar":"لَقَدْ جِئْتَ شَيْئاً إِمْراً — أي: منكراً","en":"you have done a grievous thing - that is, a monstrous one","ur":"تم نے بڑی سخت بات کی — یعنی منکر"},"levels_with":[]},{"form_id":"mfr_amr_f5","roman":"VIII","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_viii","root_type":"GT:root_type:hamzated","madi":"ائْتَمَرَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["ائتمار"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"command","pole_family":"PF:amr_command_affair","trans":["GT:transitivity:transitive_by_harf"],"trans_note":null,"ayah":"al-Qasas 28:20","gloss":{"ar":"الائتمارُ: قبولُ الأمر، ويقال للتشاور: ائتمارٌ","en":"itimar is the accepting of a command; and mutual consultation is also called itimar","ur":"ائتمار: حکم قبول کرنا؛ اور باہمی مشورے کو بھی ائتمار کہتے ہیں"},"senses":[{"sense":{"ar":"قبولُ بعضِهم أمرَ بعضٍ فيما أشار به","en":"each accepting the other''s word in what he has counselled","ur":"ایک دوسرے کی رائے کو قبول کرنا"},"example":{"ar":"إِنَّ الْمَلَأَ يَأْتَمِرُونَ بِكَ","en":"the chiefs are taking counsel about you","ur":"سردار تمہارے بارے میں مشورہ کر رہے ہیں"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.88. Two nominal rows share the word al-amr but not the pole - the affair that covers all sayings and doings, and origination proper to God - which is al-Raghib''s own division, made explicitly. He also canvasses amarna / ammarna / amarna at al-Isra 17:16 and the four kinds of uli l-amr; both are argument, not paradigm, and belong to the passage layer. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_rsl_fam', 'raghib_mufradat', 're_mfr_09a1749c423c125f', 'رسل',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 352,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"أصلُ الرِّسْلِ: الانبعاثُ على التُّؤَدة","en":"the root of risl is a setting-forth done unhurriedly","ur":"رِسْل کی اصل: نرمی و ٹھہراؤ کے ساتھ چل پڑنا"},"distinctive_note":{"ar":"يشتقّ الراغب الرسولَ من الانبعاثِ نفسِه، ويجعل الرفقَ والانبعاثَ وجهين متصوَّرين من أصلٍ واحد","en":"al-Raghib derives rasul from the setting-forth itself, and makes gentleness and setting-forth two aspects conceived from one root","ur":"الراغب رسول کو خود انبعاث سے مشتق کرتے ہیں، اور رفق و انبعاث کو ایک ہی اصل کے دو رخ بناتے ہیں"},"authors_own_words":{"ar":"وتُصُوِّر منه تارةً الرفقُ، فقيل: على رِسْلِكَ، إذا أمرتَه بالرفق، وتارةً الانبعاثُ فاشتُقَّ منه الرسول","en":"from it gentleness is sometimes conceived, so one says ala rislika when ordering someone to go gently; and sometimes the setting-forth, and from that rasul is derived","ur":"کبھی اس سے رفق کا تصور لیا گیا: عَلَى رِسْلِكَ؛ اور کبھی انبعاث کا، اور اسی سے رسول مشتق ہوا"}},"poles":[{"key":"gentleness","label":{"ar":"الرفقُ والتُّؤَدة","en":"gentleness and unhurriedness","ur":"رفق اور ٹھہراؤ"}},{"key":"sending","label":{"ar":"الإرسالُ المقابلُ للإمساك","en":"sending, the counterpart of withholding","ur":"ارسال، جو امساک کے مقابل ہے"}},{"key":"messengership","label":{"ar":"الرسولُ ومتحمِّلُ الرسالة","en":"the messenger, bearer of the message","ur":"رسول، پیغام اٹھانے والا"}}],"forms":[{"form_id":"mfr_rsl_f1","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"gentleness","pole_family":"PF:rsl_gentleness_sending","trans":[],"trans_note":null,"ayah":null,"gloss":{"ar":"الرِّسْلُ: الانبعاثُ على التُّؤَدة","en":"al-risl: setting forth unhurriedly","ur":"الرِّسْل: ٹھہراؤ کے ساتھ چل پڑنا"},"senses":[{"sense":{"ar":"الرفق","en":"gentleness","ur":"رفق"},"example":{"ar":"على رِسْلِكَ، إذا أمرتَه بالرفق","en":"ala rislika - said when you order someone to go gently","ur":"عَلَى رِسْلِكَ: جب تم کسی کو نرمی کا حکم دو"}},{"sense":{"ar":"سهولةُ السَّير","en":"ease of going","ur":"چال کی آسانی"},"example":{"ar":"ناقةٌ رِسْلَةٌ: سهلةُ السَّير، وإبلٌ مَراسيلُ: منبعثةٌ انبعاثاً سهلاً","en":"a risla she-camel goes easily; marasil camels set forth with an easy setting-forth","ur":"ناقہ رِسْلَہ: نرم رفتار؛ ابلِ مراسیل: آسانی سے چل پڑنے والے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_rsl_f2","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:sound","madi":"أَرْسَلَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إرسال"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"مُرْسِل","ism_maf_term":"GT:derivation_type:passive_participle","ism_maf":"مُرْسَل","pole":"sending","pole_family":"PF:rsl_gentleness_sending","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":"al-Anam 6:6; al-Anam 6:61; Maryam 19:83; Fatir 35:2","gloss":{"ar":"الإرسالُ يقابل الإمساك، ويقال في الإنسانِ وفي الأشياءِ المحبوبةِ والمكروهة","en":"irsal is the counterpart of withholding, and is said of a person and of things loved and hated alike","ur":"ارسال امساک کے مقابل ہے، اور انسان اور محبوب و مکروہ اشیاء دونوں میں بولا جاتا ہے"},"senses":[{"sense":{"ar":"بالتسخير","en":"by subjection","ur":"تسخیر کے ذریعے"},"example":{"ar":"وَأَرْسَلْنَا السَّماءَ عَلَيْهِمْ مِدْراراً","en":"and We sent the sky upon them pouring","ur":"اور ہم نے اُن پر آسمان کو موسلا دھار بھیجا"}},{"sense":{"ar":"ببعثِ من له اختيار","en":"by dispatching one who has choice","ur":"صاحبِ اختیار کو بھیج کر"},"example":{"ar":"وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً","en":"and He sends guardians over you","ur":"اور وہ تم پر نگہبان بھیجتا ہے"}},{"sense":{"ar":"بالتخليةِ وتركِ المنع","en":"by letting loose and leaving off restraint","ur":"چھوڑ دینے اور روک نہ لگانے سے"},"example":{"ar":"أَلَمْ تَرَ أَنَّا أَرْسَلْنَا الشَّياطِينَ عَلَى الْكافِرِينَ تَؤُزُّهُمْ أَزًّا","en":"have you not seen that We loosed the satans upon the disbelievers, inciting them fiercely","ur":"کیا تم نے نہیں دیکھا کہ ہم نے شیاطین کو کافروں پر چھوڑ دیا، جو اُنہیں ابھارتے رہتے ہیں"}}],"shahid":{"ar":"وَما يُمْسِكْ فَلا مُرْسِلَ لَهُ مِنْ بَعْدِهِ","en":"and what He withholds, none can send after Him","ur":"اور جو وہ روک لے، اُس کے بعد کوئی بھیجنے والا نہیں"},"levels_with":[]},{"form_id":"mfr_rsl_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"messengership","pole_family":"PF:rsl_gentleness_sending","trans":[],"trans_note":{"ar":"ورُسُلُ الله تارةً يُراد بها الملائكة، وتارةً يُراد بها الأنبياء","en":"and by the messengers of God are meant sometimes the angels, sometimes the prophets","ur":"اللہ کے رسولوں سے کبھی فرشتے مراد ہوتے ہیں، کبھی انبیاء"},"ayah":"al-Tawba 9:128; al-Shuara 26:16; al-Takwir 81:19","gloss":{"ar":"الرسولُ يقال تارةً للقولِ المتحمَّل، وتارةً لمتحمِّلِ القولِ والرسالة","en":"rasul is said sometimes of the message borne, sometimes of the bearer of the message","ur":"رسول کبھی اٹھائے گئے پیغام کے لیے، اور کبھی پیغام اٹھانے والے کے لیے"},"senses":[{"sense":{"ar":"متحمِّلُ الرسالة","en":"the bearer of the message","ur":"پیغام اٹھانے والا"},"example":{"ar":"لَقَدْ جاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ","en":"a messenger from among yourselves has come to you","ur":"تمہارے پاس تم ہی میں سے ایک رسول آیا"}},{"sense":{"ar":"ويقال للواحدِ والجمع","en":"and it is said of one and of many alike","ur":"اور یہ واحد و جمع دونوں پر بولا جاتا ہے"},"example":{"ar":"إِنَّا رَسُولُ رَبِّ الْعالَمِينَ","en":"we are the messenger of the Lord of the worlds","ur":"ہم ربّ العالمین کے رسول ہیں"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.352. No Form I verb is given: al-Raghib opens on the noun al-risl and moves straight to Form IV, so the first row carries form_tier noun_derivatives rather than an invented bab. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
