   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_rhm_fam', 'raghib_mufradat', 're_mfr_7c8bb302326a974c', 'رحم',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 347,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"الرَّحْمَةُ: رِقَّةٌ تقتضي الإحسانَ إلى المرحوم","en":"rahma is a tenderness that calls for kindness towards the one shown mercy","ur":"رحمت: وہ نرمی جو مرحوم کے ساتھ احسان کا تقاضا کرے"},"distinctive_note":{"ar":"يفصل الراغب معنيَي الرحمة - الرقّةَ والإحسانَ - ثمّ يقرّر أنّ الله تفرَّد بالإحسان وركَّز الرقّةَ في طبائع الناس","en":"al-Raghib separates the two senses of rahma - tenderness and kindness - then holds that God is alone in the kindness while the tenderness is fixed in human natures","ur":"الراغب رحمت کے دو معنی — رقت اور احسان — جدا کرتے ہیں، پھر کہتے ہیں کہ احسان اللہ کے ساتھ خاص ہے اور رقت انسانی طبائع میں رکھی گئی"},"authors_own_words":{"ar":"الرحمةُ من الله إنعامٌ وإفضال، ومن الآدميّين رِقّةٌ وتعطُّف","en":"mercy from God is bestowal and bounty; from human beings it is tenderness and compassion","ur":"اللہ کی طرف سے رحمت انعام و افضال ہے، اور انسانوں کی طرف سے رقت و شفقت"}},"poles":[{"key":"womb","label":{"ar":"الرَّحِمُ وما استُعير له من القرابة","en":"the womb, and kinship borrowed from it","ur":"رحم، اور اسی سے مستعار قرابت"}},{"key":"mercy","label":{"ar":"الرقّةُ المقتضيةُ للإحسان","en":"the tenderness that calls for kindness","ur":"وہ رقت جو احسان کا تقاضا کرے"}}],"forms":[{"form_id":"mfr_rhm_f1","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"رَحِمَ","mudari":"يَرْحَمُ","masdar_term":"GT:derivation_type:masdar","masadir":["رَحْمة"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":"GT:derivation_type:passive_participle","ism_maf":"مَرْحوم","pole":"mercy","pole_family":"PF:rhm_womb_mercy","trans":["GT:transitivity:transitive"],"trans_note":{"ar":"وإذا وُصف به الباري فليس يُراد به إلّا الإحسانُ المجرَّدُ دون الرقّة","en":"and when the Creator is described by it, nothing is meant but bare kindness, without tenderness","ur":"جب باری تعالیٰ اس سے موصوف ہوں تو محض احسان مراد ہوتا ہے، رقت نہیں"},"ayah":null,"gloss":{"ar":"رَحِمَهُ: أحسنَ إليه رِقّةً أو إحساناً مجرَّداً","en":"rahimahu - he was kind to him, whether out of tenderness or in bare kindness","ur":"اُس نے رحم کیا: رقت سے یا محض احسان سے بھلائی کی"},"senses":[{"sense":{"ar":"الرقّةُ المجرَّدة","en":"bare tenderness","ur":"محض رقت"},"example":{"ar":"الرَّحْمَةُ رِقَّةٌ تقتضي الإحسانَ إلى المرحوم","en":"rahma is a tenderness that calls for kindness towards the one shown mercy","ur":"رحمت وہ نرمی ہے جو مرحوم پر احسان کا تقاضا کرے"}},{"sense":{"ar":"الإحسانُ المجرَّدُ عن الرقّة، وبه يُوصف الباري","en":"kindness stripped of tenderness - and it is by this that the Creator is described","ur":"رقت سے خالی احسان، اور اسی سے باری تعالیٰ موصوف ہوتے ہیں"},"example":{"ar":"رَحِمَ اللهُ فلاناً","en":"may God have mercy on so-and-so","ur":"اللہ فلاں پر رحم کرے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_rhm_f2","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"womb","pole_family":"PF:rhm_womb_mercy","trans":[],"trans_note":null,"ayah":"al-Kahf 18:81","gloss":{"ar":"الرَّحِمُ: رَحِمُ المرأة، ومنه استُعير للقرابة لكونهم خارجين من رَحِمٍ واحدة","en":"al-rahim is the woman''s womb; from it kinship is borrowed, since kin come out of one womb","ur":"الرَّحِم: عورت کا رحم؛ اسی سے قرابت مستعار ہے، کیونکہ وہ ایک ہی رحم سے نکلے ہیں"},"senses":[{"sense":{"ar":"القرابة","en":"kinship","ur":"قرابت"},"example":{"ar":"وَأَقْرَبَ رُحْماً","en":"and nearer in kinship","ur":"اور رشتے میں زیادہ قریب"}}],"shahid":{"ar":"لمّا خلق الرَّحِمَ قال له: أنا الرحمنُ وأنت الرَّحِم، شققتُ اسمَك من اسمي، فمن وصلَك وصلتُه، ومن قطعَك بتَتُّه","en":"when He created the womb He said to it: I am al-Rahman and you are the rahim; I have split your name from My name - whoever joins you I join, and whoever severs you I cut off","ur":"جب اُس نے رحم کو پیدا کیا تو فرمایا: میں رحمن ہوں اور تو رحم ہے، میں نے تیرا نام اپنے نام سے نکالا؛ جو تجھے جوڑے میں اُسے جوڑوں، جو تجھے کاٹے میں اُسے کاٹ دوں"},"levels_with":[]},{"form_id":"mfr_rhm_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"mercy","pole_family":"PF:rhm_womb_mercy","trans":[],"trans_note":{"ar":"وقيل: إنّ الله رحمنُ الدنيا ورحيمُ الآخرة، لأنّ إحسانَه في الدنيا يعمّ المؤمنين والكافرين، وفي الآخرة يختصّ بالمؤمنين","en":"and it is said God is the Rahman of this world and the Rahim of the next, since His kindness here covers believer and denier alike, while in the hereafter it is for the believers only","ur":"کہا گیا: اللہ دنیا کے رحمن اور آخرت کے رحیم ہیں، کیونکہ دنیا میں اُن کا احسان مومن و کافر سب کو شامل ہے، اور آخرت میں مومنوں کے ساتھ خاص"},"ayah":"al-Baqara 2:182; al-Tawba 9:128; al-Araf 7:156","gloss":{"ar":"الرحمنُ والرحيمُ نحو: نَدْمانَ ونديم؛ ولا يُطلق الرحمنُ إلّا على الله","en":"al-Rahman and al-Rahim are like nadman and nadim; but al-Rahman is applied to God alone","ur":"رحمن و رحیم جیسے نَدْمان و ندیم؛ مگر رحمن صرف اللہ پر بولا جاتا ہے"},"senses":[{"sense":{"ar":"الرحمنُ: مَن وسِعَ كلَّ شيءٍ رحمةً، ولا يصحّ معناه إلّا له","en":"al-Rahman: He whose mercy has embraced everything, a meaning sound of none but Him","ur":"رحمن: جس کی رحمت نے ہر چیز کو گھیر رکھا ہے، یہ معنی اُسی کے لیے درست ہے"},"example":{"ar":"وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ","en":"and My mercy embraces all things","ur":"اور میری رحمت ہر چیز پر وسیع ہے"}},{"sense":{"ar":"الرحيمُ: الذي كثُرت رحمتُه، ويُستعمل في غيره","en":"al-Rahim: He whose mercy is abundant - and it is used of others too","ur":"رحیم: جس کی رحمت کثیر ہو، اور یہ غیر کے لیے بھی آتا ہے"},"example":{"ar":"بِالْمُؤْمِنِينَ رَؤُفٌ رَحِيمٌ","en":"to the believers he is kind and merciful","ur":"مومنوں کے لیے نہایت شفیق و مہربان"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.347. The Rahman/Rahim pairing is likened to nadman/nadim as a matter of pattern only, so no levels_with is asserted - al-Raghib is drawing an analogy of form, not claiming the two are the same. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_rbb_fam', 'raghib_mufradat', 're_mfr_16991c423780645a', 'ربب',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 336,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:doubled","block_meta":{"core":{"ar":"الرَّبُّ في الأصل: التربيةُ، وهو إنشاءُ الشيءِ حالاً فحالاً إلى حدِّ التمام","en":"al-rabb is at root the raising of a thing - bringing it up state by state to the point of completion","ur":"الرب کی اصل: تربیت، یعنی کسی چیز کو درجہ بدرجہ حدِ تمام تک پہنچانا"},"distinctive_note":{"ar":"يقرّر الراغب أنّ الربّ مصدرٌ مستعارٌ للفاعل، فلا يُطلق مجرَّداً إلّا لله، ويُقال بالإضافة له ولغيره","en":"al-Raghib holds that rabb is a verbal noun borrowed for the agent, so unqualified it is used of God alone, though in construct it is said of Him and of others","ur":"الراغب کہتے ہیں کہ ربّ مصدر ہے جو فاعل کے لیے مستعار ہوا، اس لیے مطلق صرف اللہ کے لیے، اور اضافت کے ساتھ غیر کے لیے بھی"},"authors_own_words":{"ar":"فالرَّبُّ مصدرٌ مستعارٌ للفاعل، ولا يقال الربُّ مطلقاً إلّا لله تعالى المتكفِّلِ بمصلحةِ الموجودات","en":"so rabb is a verbal noun borrowed for the agent, and rabb unqualified is said only of God, who undertakes the good of all that exists","ur":"پس ربّ مصدر ہے جو فاعل کے لیے مستعار ہے، اور مطلق ربّ صرف اللہ کے لیے بولا جاتا ہے جو موجودات کی مصلحت کے کفیل ہیں"}},"poles":[{"key":"nurture","label":{"ar":"التربيةُ والإنشاءُ إلى التمام","en":"raising, bringing to completion","ur":"تربیت اور تکمیل تک پہنچانا"}},{"key":"lordship","label":{"ar":"التكفُّلُ بمصلحةِ الموجودات","en":"undertaking the good of all that exists","ur":"موجودات کی مصلحت کا کفیل ہونا"}},{"key":"possession","label":{"ar":"الصاحبُ المالكُ بالإضافة","en":"the owner, in construct","ur":"اضافت کے ساتھ مالک و صاحب"}}],"forms":[{"form_id":"mfr_rbb_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:doubled","madi":"رَبَّ","mudari":"يَرُبُّ","masdar_term":"GT:derivation_type:masdar","masadir":["رَبّ","رِبابة"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"nurture","pole_family":"PF:rbb_nurture_lordship","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":null,"gloss":{"ar":"رَبَّهُ: أنشأه حالاً فحالاً إلى حدِّ التمام","en":"rabbahu - he brought him up state by state to the point of completion","ur":"اُس نے اُس کی تربیت کی: درجہ بدرجہ حدِ تمام تک پہنچایا"},"senses":[{"sense":{"ar":"التربية","en":"raising and bringing up","ur":"تربیت"},"example":{"ar":"يقال: رَبَّهُ، ورَبَّاهُ، ورَبَّبَهُ","en":"one says rabbahu, rabbahu (II), and rabbabahu","ur":"کہا جاتا ہے: رَبَّہُ، رَبَّاہُ، رَبَّبَہُ"}}],"shahid":{"ar":"لأن يَرُبَّني رجلٌ من قريشٍ أحبُّ إليَّ من أن يَرُبَّني رجلٌ من هوازن","en":"that a man of Quraysh should have charge of me is dearer to me than that a man of Hawazin should","ur":"مجھے یہ زیادہ پسند ہے کہ قریش کا کوئی مرد میری سرپرستی کرے، بہ نسبت اس کے کہ ہوازن کا کوئی کرے"},"levels_with":[]},{"form_id":"mfr_rbb_f2","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:doubled","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"lordship","pole_family":"PF:rbb_nurture_lordship","trans":[],"trans_note":{"ar":"ولم يكن من حقِّ الربِّ أن يُجمع، لكن أتى بلفظ الجمع فيه على حسب اعتقاداتهم، لا على ما عليه ذاتُ الشيء في نفسه","en":"by rights rabb ought not to be pluralised, but the plural is used according to their beliefs, not according to what the thing is in itself","ur":"ربّ کا جمع ہونا حق نہ تھا، مگر جمع کا لفظ اُن کے اعتقادات کے مطابق آیا، نہ کہ خود اُس شے کی حقیقت کے مطابق"},"ayah":"Saba 34:15; al-Fatiha 1:1; Al Imran 3:80; Yusuf 12:39","gloss":{"ar":"الربُّ مطلقاً: المتكفِّلُ بمصلحةِ الموجودات، ولا يقال إلّا لله","en":"rabb unqualified: He who undertakes the good of all that exists - said of God alone","ur":"مطلق ربّ: موجودات کی مصلحت کا کفیل، اور یہ صرف اللہ کے لیے"},"senses":[{"sense":{"ar":"المتكفِّلُ بمصلحةِ الموجودات","en":"He who undertakes the good of all that exists","ur":"موجودات کی مصلحت کا کفیل"},"example":{"ar":"بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ","en":"a good land and a forgiving Lord","ur":"پاکیزہ شہر اور بخشنے والا رب"}},{"sense":{"ar":"وبالإضافةِ يقال له ولغيره","en":"and in construct it is said of Him and of others","ur":"اور اضافت کے ساتھ اُس کے لیے بھی اور غیر کے لیے بھی"},"example":{"ar":"رَبِّ الْعالَمِينَ","en":"Lord of the worlds","ur":"تمام جہانوں کا رب"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_rbb_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:doubled","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"possession","pole_family":"PF:rbb_nurture_lordship","trans":[],"trans_note":null,"ayah":"Yusuf 12:42; Yusuf 12:50; Yusuf 12:23","gloss":{"ar":"ويقال: رَبُّ الدارِ ورَبُّ الفرسِ لصاحبهما","en":"and one says rabb of the house and rabb of the horse, of their owner","ur":"اور کہا جاتا ہے: ربّ الدار، ربّ الفرس، یعنی اُن کا مالک"},"senses":[{"sense":{"ar":"الصاحبُ المالك","en":"the owner and master","ur":"صاحب و مالک"},"example":{"ar":"اذْكُرْنِي عِنْدَ رَبِّكَ","en":"mention me to your master","ur":"اپنے آقا کے پاس میرا ذکر کرنا"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_rbb_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:doubled","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"nurture","pole_family":"PF:rbb_nurture_lordship","trans":[],"trans_note":{"ar":"وقيل: ربّانيٌّ لفظٌ في الأصل سريانيّ، فقلَّما يوجد في كلامهم","en":"and it is said rabbani is originally a Syriac word, which is why it is scarcely found in their speech","ur":"اور کہا گیا: ربّانی اصلاً سریانی لفظ ہے، اسی لیے اُن کے کلام میں کم ملتا ہے"},"ayah":"al-Maida 5:63; Al Imran 3:79; Al Imran 3:146","gloss":{"ar":"الرَّبَّانيُّ: قيل منسوبٌ إلى الرَّبَّان، وقيل إلى الرَّبِّ الذي هو المصدر، وقيل إلى الربِّ أي اللهِ تعالى","en":"al-rabbani: said to be derived from rabban, or from rabb the verbal noun, or from al-Rabb, that is God","ur":"ربّانی: کہا گیا رَبّان کی طرف منسوب، یا اُس ربّ کی طرف جو مصدر ہے، یا ربّ یعنی اللہ کی طرف"},"senses":[{"sense":{"ar":"الذي يَرُبُّ العلمَ ويَرُبُّ نفسَه به، وكلاهما متلازمان","en":"he who has charge of knowledge and raises himself by it - and the two are inseparable","ur":"جو علم کی تربیت کرے اور علم سے اپنی تربیت کرے، اور دونوں لازم و ملزوم ہیں"},"example":{"ar":"كُونُوا رَبَّانِيِّينَ","en":"be men of the Lord","ur":"ربّانی بن جاؤ"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_rbb_f5","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:doubled","madi":"أَرَبَّ","mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"nurture","pole_family":"PF:rbb_nurture_lordship","trans":["GT:transitivity:intransitive"],"trans_note":{"ar":"وتُصُوِّر فيه معنى الإقامة فقيل: أَرَبَّ فلانٌ بمكانِ كذا، تشبيهاً بإقامة الرَّباب","en":"the sense of staying was conceived in it, so one says arabba so-and-so in such a place, likened to the staying of the rain-clouds","ur":"اس میں اقامت کا معنی تصور کیا گیا: أَرَبَّ فلانٌ بمکانِ کذا، رَباب کے ٹھہرنے سے تشبیہ دیتے ہوئے"},"ayah":null,"gloss":{"ar":"أَرَبَّتِ السحابةُ: دامت، وحقيقتُه أنّها صارت ذاتَ تربية","en":"arabbat the cloud - it lasted; and its truth is that it came to have nurture in it","ur":"أَرَبَّتِ السحابۃ: وہ ٹھہری رہی، اور اس کی حقیقت یہ ہے کہ وہ تربیت والی ہو گئی"},"senses":[],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.336. Three nominal rows share the word al-rabb but differ by pole - absolute lordship, ownership in construct, and the rabbani - which is al-Raghib''s own division. The rabb/rabib/rabiba affinal terms and al-rabab (cloud) are further derivations he treats and are left to the passage layer. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
