VALUES ('blk_mfr_sm3_fam', 'raghib_mufradat', 're_mfr_7823d6f6c779c6b5', 'سمع',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 425,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"السَّمْعُ: قوّةٌ في الأذن بها تُدرَك الأصوات، وفعلُه يقال له السَّمْعُ أيضاً","en":"al-sam is a faculty in the ear by which sounds are perceived; its act is also called sam","ur":"السَّمْع: کان میں وہ قوت جس سے آوازیں پائی جاتی ہیں، اور اِس کا فعل بھی سَمْع کہلاتا ہے"},"distinctive_note":{"ar":"يرتّب الراغب السمعَ في أربع: الأذنُ، والفعلُ، والفهمُ، والطاعةُ؛ ويقرأ ﴿سَمِعْنا وَعَصَيْنا﴾ و﴿سَمِعْنا وَأَطَعْنا﴾ على الفهم لا على مجرّد الإدراك","en":"al-Raghib orders sam in four: the ear, the act, understanding, and obedience; and he reads \"we heard and disobeyed\" and \"we heard and obeyed\" as understanding, not bare perception","ur":"الراغب سمع کو چار میں مرتب کرتے ہیں: کان، فعل، فہم، اطاعت؛ اور ﴿سَمِعْنا وَعَصَيْنا﴾ و ﴿سَمِعْنا وَأَطَعْنا﴾ کو فہم پر محمول کرتے ہیں"},"authors_own_words":{"ar":"وكلُّ موضعٍ أثبت اللهُ السمعَ للمؤمنين، أو نفى عن الكافرين، أو حثَّ على تحرّيه، فالقصدُ به إلى تصوُّرِ المعنى والتفكُّرِ فيه","en":"wherever God affirms hearing of the believers, or denies it of the deniers, or urges its pursuit, what is meant is grasping the sense and pondering it","ur":"ہر وہ مقام جہاں اللہ نے مومنوں کے لیے سمع ثابت کیا، یا کافروں سے نفی کی، یا اُس کی تلاش پر ابھارا — وہاں مقصود معنی کا تصور اور اُس میں تفکر ہے"}},"poles":[{"key":"hearing","label":{"ar":"قوّةُ الأذنِ وفعلُها","en":"the ear''s faculty and its act","ur":"کان کی قوت اور اُس کا فعل"}},{"key":"understanding","label":{"ar":"الفهمُ وتصوُّرُ المعنى","en":"understanding and grasping the sense","ur":"فہم اور معنی کا تصور"}},{"key":"obedience","label":{"ar":"الطاعةُ والائتمار","en":"obedience, taking the order","ur":"اطاعت اور حکم ماننا"}}],"forms":[{"form_id":"mfr_sm3_f1","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"سَمِعَ","mudari":"يَسْمَعُ","masdar_term":"GT:derivation_type:masdar","masadir":["سَمْع","سَماع"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"سامِع","ism_maf_term":"GT:derivation_type:passive_participle","ism_maf":"مَسْموع","pole":"hearing","pole_family":"PF:sma_hearing_heeding","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":"al-Baqara 2:7; Qaf 50:37; al-Nisa 4:46; al-Baqara 2:285","gloss":{"ar":"سَمِعَ سَمْعاً: أدرك الصوتَ بقوّةِ الأذن","en":"samia saman - he perceived the sound by the ear''s faculty","ur":"سَمِعَ سَمْعاً: کان کی قوت سے آواز کو پایا"},"senses":[{"sense":{"ar":"الأذنُ نفسُها","en":"the ear itself","ur":"خود کان"},"example":{"ar":"خَتَمَ اللَّهُ عَلى قُلُوبِهِمْ وَعَلى سَمْعِهِمْ","en":"God has sealed their hearts and their hearing","ur":"اللہ نے اُن کے دلوں اور اُن کے کانوں پر مہر لگا دی"}},{"sense":{"ar":"الفهم","en":"understanding","ur":"فہم"},"example":{"ar":"سَمِعْنا وَعَصَيْنا، أي: فهمنا قولَك ولم نأتمرْ لك","en":"we heard and disobeyed - that is, we understood your word and did not take your order","ur":"ہم نے سنا اور نافرمانی کی، یعنی: تیری بات سمجھ لی اور تیرا حکم نہ مانا"}},{"sense":{"ar":"الطاعة","en":"obedience","ur":"اطاعت"},"example":{"ar":"سَمِعْنا وَأَطَعْنا، أي: فهمنا وارتسمنا","en":"we heard and obeyed - that is, we understood and complied","ur":"ہم نے سنا اور مانا، یعنی: سمجھ لیا اور تعمیل کی"}}],"shahid":{"ar":"وَإِذا تُتْلى عَلَيْهِمْ آياتُنا قالُوا قَدْ سَمِعْنا","en":"and when Our signs are recited to them they say: we have heard","ur":"اور جب اُن پر ہماری آیتیں پڑھی جائیں تو کہتے ہیں: ہم نے سن لیا"},"levels_with":[]},{"form_id":"mfr_sm3_f2","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:sound","madi":"أَسْمَعَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إسماع"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":"GT:derivation_type:passive_participle","ism_maf":"مُسْمَع","pole":"understanding","pole_family":"PF:sma_hearing_heeding","trans":["GT:transitivity:ditransitive"],"trans_note":{"ar":"و﴿وَاسْمَعْ غَيْرَ مُسْمَعٍ﴾ يقال على وجهين: دعاءٌ على الإنسان بالصَّمم، ودعاءٌ له","en":"\"and hear, not made to hear\" is said in two ways: a curse of deafness upon a man, and a prayer for him","ur":"﴿وَاسْمَعْ غَيْرَ مُسْمَعٍ﴾ دو طرح بولا جاتا ہے: بہرے پن کی بددعا، اور دعا"},"ayah":"al-Anfal 8:23; al-Naml 27:80; al-Nisa 4:46","gloss":{"ar":"أَسْمَعَهُ: أفهمه بأن جعل له قوّةً يفهم بها","en":"asmaahu - he made him understand, by giving him a faculty to understand with","ur":"أَسْمَعَہُ: اُسے سمجھایا، اُسے وہ قوت دے کر جس سے وہ سمجھے"},"senses":[{"sense":{"ar":"الإفهام","en":"making to understand","ur":"سمجھانا"},"example":{"ar":"وَلَوْ عَلِمَ اللَّهُ فِيهِمْ خَيْراً لَأَسْمَعَهُمْ","en":"had God known any good in them He would have made them hear","ur":"اگر اللہ اُن میں کوئی بھلائی جانتا تو ضرور اُنہیں سنا دیتا"}},{"sense":{"ar":"السبُّ، وذلك متعارَفٌ فيه","en":"reviling - the usage is well known","ur":"گالی دینا، جو اِس میں معروف ہے"},"example":{"ar":"أَسْمَعْتُ فلاناً: إذا سببتَه","en":"asmatu so-and-so - when you have reviled him","ur":"میں نے فلاں کو أَسْمَعْتُ کیا: یعنی گالی دی"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_sm3_f3","roman":"VIII","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_viii","root_type":"GT:root_type:sound","madi":"اسْتَمَعَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["استماع"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"hearing","pole_family":"PF:sma_hearing_heeding","trans":["GT:transitivity:transitive_by_harf"],"trans_note":null,"ayah":"al-Isra 17:47; Muhammad 47:16; Yunus 10:42","gloss":{"ar":"الاستماعُ: الإصغاء","en":"istima: giving ear","ur":"استماع: کان لگانا"},"senses":[{"sense":{"ar":"الإصغاءُ إلى القول","en":"giving ear to what is said","ur":"بات کی طرف کان لگانا"},"example":{"ar":"نَحْنُ أَعْلَمُ بِما يَسْتَمِعُونَ بِهِ، إِذْ يَسْتَمِعُونَ إِلَيْكَ","en":"We know best what they listen for, when they listen to you","ur":"ہم خوب جانتے ہیں کہ وہ کیا سننے آتے ہیں، جب وہ تمہاری طرف کان لگاتے ہیں"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_sm3_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"hearing","pole_family":"PF:sma_hearing_heeding","trans":[],"trans_note":null,"ayah":"al-Mujadala 58:1; Al Imran 3:181","gloss":{"ar":"إذا وُصف اللهُ بالسَّمعِ فالمرادُ به علمُه بالمسموعات وتحرّيه بالمجازاةِ بها","en":"when God is described by hearing, what is meant is His knowing of what is heard and His attending to requite by it","ur":"جب اللہ سمع سے موصوف ہوں تو مراد مسموعات کا اُن کا علم اور اُن پر جزا دینا ہے"},"senses":[{"sense":{"ar":"علمُ الله بالمسموعات","en":"God''s knowing of what is heard","ur":"مسموعات کا اللہ کا علم"},"example":{"ar":"قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجادِلُكَ فِي زَوْجِها","en":"God has heard the words of her who disputes with you about her husband","ur":"اللہ نے اُس عورت کی بات سن لی جو اپنے شوہر کے بارے میں تم سے جھگڑ رہی تھی"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.425. The four senses of the Form I row are al-Raghib''s own graded list (ear, act, understanding, obedience), not an editorial spread, which is why they sit as senses under one row rather than as separate forms. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_ilm_fam', 'raghib_mufradat', 're_mfr_2a5a88a8d1c32df6', 'علم',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 580,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:sound","block_meta":{"core":{"ar":"العِلْمُ: إدراكُ الشيءِ بحقيقتِه","en":"ilm is the grasping of a thing as it truly is","ur":"علم: کسی چیز کو اُس کی حقیقت کے ساتھ پا لینا"},"distinctive_note":{"ar":"يقسم الراغب العلمَ ثلاثَ قسمات متقاطعة: بالتعدية إلى مفعولٍ أو مفعولين، وبالنظريِّ والعمليِّ، وبالعقليِّ والسمعيِّ","en":"al-Raghib cuts ilm three intersecting ways: by taking one object or two, by theoretical and practical, and by rational and revealed","ur":"الراغب علم کو تین متقاطع تقسیموں میں بانٹتے ہیں: ایک یا دو مفعول کے اعتبار سے، نظری و عملی، اور عقلی و سمعی"},"authors_own_words":{"ar":"وأَعْلَمْتُهُ وعَلَّمْتُهُ في الأصلِ واحد، إلّا أنّ الإعلامَ اختصَّ بما كان بإخبارٍ سريع، والتعليمَ اختصَّ بما يكون بتكريرٍ وتكثيرٍ حتى يحصل منه أثرٌ في نفسِ المتعلِّم","en":"alamtuhu and allamtuhu are one at root, save that ilam belongs to what is done by swift announcement, and talim to what is done by repeating and multiplying until an effect settles in the learner''s soul","ur":"أَعْلَمْتُهُ اور عَلَّمْتُهُ اصل میں ایک ہیں، مگر اعلام تیز خبر کے ساتھ خاص ہے، اور تعلیم تکرار و تکثیر کے ساتھ یہاں تک کہ متعلم کے نفس میں اثر پیدا ہو"}},"poles":[{"key":"knowing","label":{"ar":"إدراكُ الشيءِ بحقيقتِه","en":"grasping a thing as it truly is","ur":"شے کو اُس کی حقیقت کے ساتھ پانا"}},{"key":"teaching","label":{"ar":"التعليمُ والإعلام","en":"teaching and informing","ur":"تعلیم اور اعلام"}},{"key":"mark","label":{"ar":"العَلَمُ: الأثرُ الذي يُعلَم به الشيء","en":"the alam: the mark by which a thing is known","ur":"عَلَم: وہ نشان جس سے چیز پہچانی جائے"}},{"key":"world","label":{"ar":"العالَمُ: ما يُعلَم به الصانع","en":"the alam: that by which the Maker is known","ur":"عالَم: وہ جس سے صانع پہچانا جائے"}}],"forms":[{"form_id":"mfr_ilm_f1","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:sound","madi":"عَلِمَ","mudari":"يَعْلَمُ","masdar_term":"GT:derivation_type:masdar","masadir":["عِلْم"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"عالِم","ism_maf_term":"GT:derivation_type:passive_participle","ism_maf":"مَعْلوم","pole":"knowing","pole_family":"PF:ilm_knowing_marking","trans":["GT:transitivity:transitive","GT:transitivity:ditransitive"],"trans_note":{"ar":"والعِلْمُ من وجهٍ ضربان: نظريٌّ وعمليٌّ؛ ومن وجهٍ آخر ضربان: عقليٌّ وسمعيٌّ","en":"and ilm is, from one angle, theoretical and practical; from another, rational and revealed","ur":"اور علم ایک اعتبار سے نظری و عملی ہے، اور دوسرے اعتبار سے عقلی و سمعی"},"ayah":"al-Anfal 8:60; al-Mumtahana 60:10","gloss":{"ar":"العِلْمُ ضربان: إدراكُ ذاتِ الشيء، والحكمُ عليه بوجودِ شيءٍ له أو نفيِه عنه","en":"ilm is of two kinds: grasping the thing''s essence, and judging that something belongs to it or is denied of it","ur":"علم دو قسم ہے: شے کی ذات کا ادراک، اور اُس پر کسی چیز کے ثبوت یا نفی کا حکم"},"senses":[{"sense":{"ar":"المتعدّي إلى مفعولٍ واحد: إدراكُ ذاتِ الشيء","en":"that which takes one object: grasping the thing''s essence","ur":"ایک مفعول کی طرف متعدی: شے کی ذات کا ادراک"},"example":{"ar":"لا تَعْلَمُونَهُمُ اللَّهُ يَعْلَمُهُمْ","en":"you do not know them; God knows them","ur":"تم اُنہیں نہیں جانتے، اللہ اُنہیں جانتا ہے"}},{"sense":{"ar":"المتعدّي إلى مفعولين: الحكمُ على الشيء","en":"that which takes two objects: judging about the thing","ur":"دو مفعولوں کی طرف متعدی: شے پر حکم لگانا"},"example":{"ar":"فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِناتٍ","en":"if you know them to be believing women","ur":"پھر اگر تم اُنہیں مومنہ جان لو"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_ilm_f2","roman":"II","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_ii","root_type":"GT:root_type:sound","madi":"عَلَّمَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["تعليم"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"teaching","pole_family":"PF:ilm_knowing_marking","trans":["GT:transitivity:ditransitive"],"trans_note":null,"ayah":"al-Rahman 55:1-2; al-Alaq 96:4; al-Baqara 2:31; al-Kahf 18:65","gloss":{"ar":"التعليمُ اختصَّ بما يكون بتكريرٍ وتكثيرٍ حتى يحصل منه أثرٌ في نفسِ المتعلِّم","en":"talim belongs to what is done by repeating and multiplying until an effect settles in the learner''s soul","ur":"تعلیم اُس کے ساتھ خاص ہے جو تکرار و تکثیر سے ہو یہاں تک کہ متعلم کے نفس میں اثر پیدا ہو"},"senses":[{"sense":{"ar":"تنبيهُ النفسِ لتصوُّرِ المعاني","en":"rousing the soul to grasp meanings","ur":"معانی کے تصور کے لیے نفس کو متوجہ کرنا"},"example":{"ar":"الرَّحْمنُ عَلَّمَ الْقُرْآنَ","en":"the Merciful taught the Quran","ur":"رحمن نے قرآن سکھایا"}},{"sense":{"ar":"إلقاءُ القوّةِ في الرُّوع","en":"casting the faculty into the heart","ur":"دل میں قوت ڈال دینا"},"example":{"ar":"وَعَلَّمَ آدَمَ الْأَسْماءَ كُلَّها","en":"and He taught Adam the names, all of them","ur":"اور اُس نے آدم کو سارے نام سکھائے"}}],"shahid":null,"levels_with":["mfr_ilm_f3"]},{"form_id":"mfr_ilm_f3","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:sound","madi":"أَعْلَمَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إعلام"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"teaching","pole_family":"PF:ilm_knowing_marking","trans":["GT:transitivity:ditransitive"],"trans_note":null,"ayah":"al-Hujurat 49:16","gloss":{"ar":"الإعلامُ اختصَّ بما كان بإخبارٍ سريع","en":"ilam belongs to what is done by swift announcement","ur":"اعلام اُس کے ساتھ خاص ہے جو تیز خبر سے ہو"},"senses":[{"sense":{"ar":"الإخبارُ السريع","en":"swift announcement","ur":"تیز خبر دینا"},"example":{"ar":"وربّما استُعمل التعليمُ في معنى الإعلامِ إذا كان فيه تكرير: أَتُعَلِّمُونَ اللَّهَ بِدِينِكُمْ","en":"and talim is sometimes used in the sense of ilam when repetition is in it: \"do you inform God of your religion\"","ur":"اور کبھی تعلیم اعلام کے معنی میں آتی ہے جب اُس میں تکرار ہو: ﴿أَتُعَلِّمُونَ اللَّهَ بِدِينِكُمْ﴾"}}],"shahid":null,"levels_with":["mfr_ilm_f2"]},{"form_id":"mfr_ilm_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"mark","pole_family":"PF:ilm_knowing_marking","trans":[],"trans_note":null,"ayah":"al-Shura 42:32; al-Rahman 55:24","gloss":{"ar":"العَلَمُ: الأثرُ الذي يُعلَم به الشيء، كعَلَمِ الطريقِ وعَلَمِ الجيش","en":"al-alam: the mark by which a thing is known, like the road''s marker and the army''s standard","ur":"العَلَم: وہ نشان جس سے چیز پہچانی جائے، جیسے راستے کا نشان اور لشکر کا جھنڈا"},"senses":[{"sense":{"ar":"الأثرُ الدالّ، وسُمّي الجبلُ عَلَماً لذلك","en":"the indicating mark - and a mountain is called alam for this","ur":"دلالت کرنے والا نشان، اسی لیے پہاڑ کو عَلَم کہا گیا"},"example":{"ar":"وَمِنْ آياتِهِ الْجَوارِ فِي الْبَحْرِ كَالْأَعْلامِ","en":"and of His signs are the ships running in the sea like mountains","ur":"اور اُس کی نشانیوں میں سمندر میں پہاڑوں جیسے چلنے والے جہاز ہیں"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_ilm_f5","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"world","pole_family":"PF:ilm_knowing_marking","trans":[],"trans_note":{"ar":"وجُعل بناؤه على هذه الصيغةِ لكونِه كالآلة","en":"and it was built on this pattern because it is like an instrument","ur":"اور اِس صیغے پر اِس کی بناوٹ اِس لیے ہے کہ یہ آلے کی مانند ہے"},"ayah":"al-Fatiha 1:1; al-Baqara 2:47","gloss":{"ar":"العالَمُ: اسمٌ للفَلَكِ وما يحويه، وهو في الأصلِ اسمٌ لما يُعلَم به كالطابَعِ والخاتَم","en":"al-alam is a name for the sphere and what it holds; at root it names that by which something is known, like a stamp or a seal","ur":"العالَم: فلک اور اُس کے مشمولات کا نام، اور اصل میں وہ نام ہے جس سے کوئی چیز جانی جائے، جیسے مہر اور خاتم"},"senses":[{"sense":{"ar":"آلةٌ في الدلالةِ على صانعِه، ولهذا أحالنا اللهُ عليه في معرفةِ وحدانيّتِه","en":"an instrument for pointing to its Maker - which is why God referred us to it for knowing His oneness","ur":"اپنے صانع پر دلالت کا آلہ، اسی لیے اللہ نے وحدانیت کی معرفت میں ہمیں اِسی کی طرف پھیرا"},"example":{"ar":"الْحَمْدُ لِلَّهِ رَبِّ الْعالَمِينَ","en":"praise be to God, Lord of the worlds","ur":"سب تعریف اللہ کے لیے جو تمام جہانوں کا رب ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_ilm_f6","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:sound","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"knowing","pole_family":"PF:ilm_knowing_marking","trans":[],"trans_note":{"ar":"وفي ﴿عالِمُ الْغَيْبِ فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً إِلَّا مَنِ ارْتَضى مِنْ رَسُولٍ﴾ إشارةٌ أنّ لله علماً يخصّ به أولياءه","en":"in \"Knower of the unseen, He discloses His unseen to none but a messenger He has approved\" there is a sign that God has a knowledge He reserves for His friends","ur":"﴿عالِمُ الْغَيْبِ...﴾ میں اشارہ ہے کہ اللہ کے پاس ایک علم ہے جو وہ اپنے اولیاء کے ساتھ خاص کرتے ہیں"},"ayah":"al-Maida 5:109; al-Haqqa 69:18; al-Jinn 72:26-27","gloss":{"ar":"العالِمُ في وصفِ الله: الذي لا يخفى عليه شيء","en":"al-Alim, said of God: He from whom nothing is hidden","ur":"اللہ کی صفت میں العالِم: وہ جس پر کچھ پوشیدہ نہیں"},"senses":[{"sense":{"ar":"لا تخفى عليه خافية","en":"no hidden thing is hidden from Him","ur":"کوئی چھپی بات اُس سے چھپی نہیں"},"example":{"ar":"عَلَّامُ الْغُيُوبِ","en":"the Knower of all that is unseen","ur":"غیبوں کا خوب جاننے والا"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[{"key":"talim_ilam","members":["mfr_ilm_f2","mfr_ilm_f3"],"claim":{"ar":"وأَعْلَمْتُهُ وعَلَّمْتُهُ في الأصلِ واحد","en":"alamtuhu and allamtuhu are one at root","ur":"أَعْلَمْتُهُ اور عَلَّمْتُهُ اصل میں ایک ہیں"},"qualifier":{"ar":"إلّا أنّ الإعلامَ اختصَّ بالإخبارِ السريع، والتعليمَ بالتكريرِ والتكثير","en":"save that ilam belongs to swift announcement and talim to repetition and multiplying","ur":"مگر اعلام تیز خبر کے ساتھ خاص ہے اور تعلیم تکرار و تکثیر کے ساتھ"}}],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.580. levels_with is asserted between Form II and Form IV because al-Raghib makes an explicit identity claim (fi l-asli wahid) before distinguishing them; the distinction is carried as the group qualifier, not as a denial of the claim. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_smw_fam', 'raghib_mufradat', 're_mfr_8918e9ba728222e5', 'سمو',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 427,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:defective_w","block_meta":{"core":{"ar":"سَماءُ كلِّ شيءٍ: أعلاه","en":"the sama of anything is its highest part","ur":"ہر چیز کی سماء: اُس کا سب سے اونچا حصہ"},"distinctive_note":{"ar":"يجعل الراغب السماءَ والأرضَ نسبيّتين: كلُّ سماءٍ بالإضافة إلى ما دونها سماء، وبالإضافة إلى ما فوقها أرض، إلّا السماءَ العليا","en":"al-Raghib makes sky and earth relative terms: every sky is sky in relation to what is below it and earth in relation to what is above it - except the highest sky","ur":"الراغب سماء و ارض کو نسبی بناتے ہیں: ہر سماء اپنے نیچے والے کی نسبت سماء ہے اور اوپر والے کی نسبت ارض، سوائے سماءِ علیا کے"},"authors_own_words":{"ar":"قال بعضهم: كلُّ سماءٍ بالإضافة إلى ما دونها فسماء، وبالإضافة إلى ما فوقها فأرضٌ إلّا السماءَ العليا فإنّها سماءٌ بلا أرض","en":"someone has said: every sky, in relation to what is beneath it, is sky, and in relation to what is above it, earth - except the highest sky, which is sky with no earth above it","ur":"بعض نے کہا: ہر سماء اپنے نیچے کی نسبت سماء ہے اور اوپر کی نسبت ارض، مگر سماءِ علیا جو بغیر ارض کے سماء ہے"}},"poles":[{"key":"height","label":{"ar":"السُّمُوُّ: الارتفاع","en":"sumuww: rising high","ur":"سُمُوّ: بلندی"}},{"key":"sky","label":{"ar":"السماءُ المقابلةُ للأرض","en":"the sky, counterpart of the earth","ur":"سماء، جو زمین کے مقابل ہے"}},{"key":"name","label":{"ar":"الاسمُ: ما يُعرَف به ذاتُ الشيء","en":"the ism: what a thing''s essence is known by","ur":"اسم: وہ جس سے شے کی ذات پہچانی جائے"}}],"forms":[{"form_id":"mfr_smw_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:defective_w","madi":"سَمَا","mudari":"يَسْمُو","masdar_term":"GT:derivation_type:masdar","masadir":["سُمُوّ"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"height","pole_family":"PF:smw_height_sky_name","trans":["GT:transitivity:intransitive"],"trans_note":{"ar":"والسَّماوةُ: الشخصُ العالي","en":"and al-samawa is the tall figure seen from afar","ur":"اور السَّماوۃ: اونچا نظر آنے والا وجود"},"ayah":null,"gloss":{"ar":"سَمَا يَسْمُو سُمُوّاً: ارتفع","en":"sama yasmu sumuwwan - it rose high","ur":"سَمَا يَسْمُو سُمُوّاً: بلند ہوا"},"senses":[{"sense":{"ar":"العلوُّ، وسماءُ كلِّ شيءٍ أعلاه","en":"height - and the sama of anything is its top","ur":"بلندی، اور ہر چیز کی سماء اُس کا اعلیٰ حصہ"},"example":{"ar":"وأحمرَ كالدِّيباجِ أمّا سماؤُه ... فرَيَّا وأمّا أرضُه فمَحُولُ","en":"a chestnut like brocade: as for his sky it is lush, and as for his earth it is barren","ur":"ایک سرخ گھوڑا دیباج جیسا: اُس کی سماء شاداب اور اُس کی ارض بنجر"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_smw_f2","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:defective_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"sky","pole_family":"PF:smw_height_sky_name","trans":[],"trans_note":{"ar":"ووجهُ تذكيرِها وتأنيثِها أنّها كالنَّخلِ في الشجر، من أسماءِ الجنسِ الذي يُذكَّر ويُؤنَّث","en":"the reason it is both masculine and feminine is that it is like nakhl among trees, one of the generic nouns treated either way","ur":"اِس کے تذکیر و تانیث کی وجہ یہ ہے کہ یہ درختوں میں نخل کی مانند ہے، اسمِ جنس جو مذکر بھی ہوتا ہے اور مؤنث بھی"},"ayah":"al-Talaq 65:12; al-Baqara 2:29; al-Muzzammil 73:18; al-Inshiqaq 84:1","gloss":{"ar":"السماءُ المقابلُ للأرضِ مؤنّثةٌ وقد تُذكَّر، وتُستعمل للواحدِ والجمع","en":"the sky that is counterpart to the earth is feminine, though sometimes made masculine, and is used of one and of many","ur":"زمین کے مقابل سماء مؤنث ہے اور کبھی مذکر بھی، اور واحد و جمع دونوں کے لیے آتی ہے"},"senses":[{"sense":{"ar":"الجرمُ المقابلُ للأرض، وهو نسبيٌّ بالإضافة","en":"the body opposite the earth - a relative term in construct","ur":"زمین کے مقابل جرم، اور یہ اضافت میں نسبی ہے"},"example":{"ar":"اللَّهُ الَّذِي خَلَقَ سَبْعَ سَماواتٍ وَمِنَ الْأَرْضِ مِثْلَهُنَّ","en":"God who created seven heavens, and of the earth their like","ur":"اللہ جس نے سات آسمان بنائے اور زمین سے بھی اُن جیسی"}},{"sense":{"ar":"المطرُ، سُمّي سماءً لخروجِه منها؛ وسُمّي النباتُ سماءً، إمّا لكونِه من المطر، وإمّا لارتفاعِه عن الأرض","en":"the rain, called sama because it comes out of it; and plants are called sama, either as coming from the rain, or for rising up off the earth","ur":"بارش کو سماء کہا گیا کیونکہ وہ اُسی سے نکلتی ہے؛ اور نبات کو بھی، یا بارش سے ہونے کے سبب یا زمین سے بلند ہونے کے سبب"},"example":{"ar":"السَّماءُ مُنْفَطِرٌ بِهِ","en":"the sky splitting apart by it","ur":"آسمان اُس سے پھٹ جانے والا ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_smw_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:defective_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"name","pole_family":"PF:smw_height_sky_name","trans":[],"trans_note":{"ar":"ولا يعرف الإنسانُ الاسمَ فيكون عارفاً لمسمَّاه إلّا إذا عرف ذاتَه","en":"a person does not know a name and thereby know what it names, unless he knows the thing itself","ur":"انسان محض نام جان کر مسمّٰی کا عارف نہیں ہو جاتا جب تک اُس کی ذات نہ جانے"},"ayah":"al-Fatiha 1:1; al-Baqara 2:31; Yusuf 12:40","gloss":{"ar":"الاسمُ: ما يُعرَف به ذاتُ الشيء، وأصلُه سِمْوٌ من السُّمُوّ","en":"al-ism: what a thing''s essence is known by; its origin is simw, from sumuww","ur":"الاسم: وہ جس سے شے کی ذات پہچانی جائے، اور اِس کی اصل سِمْو ہے، سُمُوّ سے"},"senses":[{"sense":{"ar":"ما به رُفِع ذكرُ المسمَّى فيُعرَف به","en":"that by which the named one''s mention is raised, so that he is known by it","ur":"وہ جس سے مسمّٰی کا ذکر بلند ہو اور وہ پہچانا جائے"},"example":{"ar":"بِسْمِ اللَّهِ","en":"in the name of God","ur":"اللہ کے نام سے"}},{"sense":{"ar":"أسماءٌ لا مسمَّياتِ لها","en":"names with nothing named by them","ur":"ایسے نام جن کا کوئی مسمّٰی نہیں"},"example":{"ar":"ما تَعْبُدُونَ مِنْ دُونِهِ إِلَّا أَسْماءً سَمَّيْتُمُوها","en":"you worship, apart from Him, nothing but names you have named","ur":"تم اُس کے سوا صرف اُن ناموں کو پوجتے ہو جو تم نے رکھ لیے"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.427. The entry has no printed TOC heading of its own in the Shamela text - it runs inline after samn as \"sama\" - which is why it was missed on an earlier heading-only pass. The ism material is the same article, not a separate root. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
