VALUES ('blk_mfr_ard_fam', 'raghib_mufradat', 're_mfr_78e2b90766ba54a3', 'ارض',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 73,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:hamzated","block_meta":{"core":{"ar":"الأرضُ: الجِرْمُ المقابلُ للسماء، وجمعُه أَرَضون","en":"al-ard is the body opposite the sky; its plural is aradun","ur":"الأرض: وہ جرم جو آسمان کے مقابل ہے، جمع أَرَضون"},"distinctive_note":{"ar":"يلاحظ الراغب أنّ الأرضَ لا تجيء مجموعةً في القرآن، ويقرأ إحياءَ الأرضِ بعد موتِها عبارةً عن كلِّ تكوينٍ بعد إفساد","en":"al-Raghib notes that ard never appears pluralised in the Quran, and reads the reviving of the earth after its death as standing for every making-anew after ruin","ur":"الراغب نوٹ کرتے ہیں کہ قرآن میں ارض جمع نہیں آتی، اور زمین کے مرنے کے بعد جی اٹھنے کو ہر افساد کے بعد تکوین سے تعبیر کرتے ہیں"},"authors_own_words":{"ar":"ويُعبَّر بها عن أسفلِ الشيء، كما يُعبَّر بالسماءِ عن أعلاه","en":"and it is used for the lowest part of a thing, as sama is used for its highest","ur":"اور اِس سے شے کے نچلے حصے کی تعبیر کی جاتی ہے، جیسے سماء سے اُس کے بالائی حصے کی"}},"poles":[{"key":"earth","label":{"ar":"الجِرْمُ المقابلُ للسماء","en":"the body opposite the sky","ur":"آسمان کے مقابل جرم"}},{"key":"lowness","label":{"ar":"أسفلُ الشيء","en":"the lowest part of a thing","ur":"شے کا نچلا حصہ"}},{"key":"fertility","label":{"ar":"حُسنُ النبتِ والتمكُّنُ في الأرض","en":"good growth, taking hold in the ground","ur":"نبات کی خوبی اور زمین میں جم جانا"}}],"forms":[{"form_id":"mfr_ard_f1","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hamzated","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"earth","pole_family":"PF:ard_earth_lowness","trans":[],"trans_note":{"ar":"وهو عبارةٌ عن كلِّ تكوينٍ بعد إفساد، وعَوْدٍ بعد بدء؛ ولذلك قال بعضُ المفسّرين: يعني به تليينَ القلوبِ بعد قساوتِها","en":"it stands for every making-anew after ruin and every return after a beginning; which is why some exegetes said it means the softening of hearts after their hardness","ur":"یہ ہر افساد کے بعد تکوین اور ہر ابتدا کے بعد عود کی تعبیر ہے؛ اسی لیے بعض مفسرین نے کہا: اِس سے دلوں کا سختی کے بعد نرم ہونا مراد ہے"},"ayah":"al-Hadid 57:17","gloss":{"ar":"الأرضُ: الجِرْمُ المقابلُ للسماء، ولا تجيءُ مجموعةً في القرآن","en":"al-ard: the body opposite the sky - and it never comes pluralised in the Quran","ur":"الأرض: آسمان کے مقابل جرم، اور قرآن میں یہ جمع نہیں آتی"},"senses":[{"sense":{"ar":"الجِرْمُ المقابلُ للسماء","en":"the body opposite the sky","ur":"آسمان کے مقابل جرم"},"example":{"ar":"اعْلَمُوا أَنَّ اللَّهَ يُحْيِ الْأَرْضَ بَعْدَ مَوْتِها","en":"know that God revives the earth after its death","ur":"جان لو کہ اللہ زمین کو اُس کے مرنے کے بعد زندہ کرتا ہے"}},{"sense":{"ar":"أسفلُ الشيء، كما يُعبَّر بالسماءِ عن أعلاه","en":"the lowest part of a thing, as the sky stands for its highest","ur":"شے کا نچلا حصہ، جیسے سماء سے اُس کا بالائی حصہ"},"example":{"ar":"أمّا سماؤُه فرَيَّا وأمّا أرضُه فمَحُولُ","en":"as for his sky it is lush, and as for his earth it is barren","ur":"اُس کی سماء شاداب اور اُس کی ارض بنجر"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_ard_f2","roman":"V","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_v","root_type":"GT:root_type:hamzated","madi":"تَأَرَّضَ","mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"fertility","pole_family":"PF:ard_earth_lowness","trans":["GT:transitivity:intransitive"],"trans_note":{"ar":"ويقال: أرضٌ أريضةٌ، أي: حسنةُ النبت","en":"and one says ardun aridatun - a land of good growth","ur":"اور کہا جاتا ہے: أرضٌ أریضۃ، یعنی اچھی روئیدگی والی زمین"},"ayah":null,"gloss":{"ar":"تأرَّضَ النبتُ: تمكَّن على الأرضِ فكثُر","en":"taarrada the plant - it took hold on the ground and grew abundant","ur":"تأرَّضَ النبت: زمین پر جم گیا اور بڑھ گیا"},"senses":[{"sense":{"ar":"التمكُّنُ على الأرض","en":"taking hold upon the ground","ur":"زمین پر جم جانا"},"example":{"ar":"وتأرَّضَ الجديُ: إذا تناول نبتَ الأرض","en":"and taarrada the kid - when it takes the ground''s herbage","ur":"اور تأرَّضَ الجدی: جب بکری کا بچہ زمین کی گھاس کھائے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_ard_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hamzated","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":"GT:derivation_type:passive_participle","ism_maf":"مَأْروضة","pole":"earth","pole_family":"PF:ard_earth_lowness","trans":[],"trans_note":{"ar":"يقال: أُرِضَتِ الخشبةُ فهي مأروضة","en":"one says: the wood was urida - so it is marud, worm-eaten","ur":"کہا جاتا ہے: أُرِضَتِ الخشبۃ، پس وہ مأروضہ ہے"},"ayah":null,"gloss":{"ar":"الأَرَضَةُ: الدودةُ التي تقع في الخشبِ من الأرض","en":"al-arada: the worm that gets into wood, from the ground","ur":"الأَرَضَۃ: وہ کیڑا جو زمین سے لکڑی میں لگ جاتا ہے"},"senses":[],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.73. A short article with no Form I active verb: the only Form I citation is the passive urida (of worm-eaten wood), which is carried as a trans_note on the arada row rather than as an invented active madi with a guessed bab. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
