VALUES ('blk_mfr_alh_fam', 'raghib_mufradat', 're_mfr_19c9abde7b3d4082', 'اله',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 82,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:hamzated","block_meta":{"core":{"ar":"اللهُ: قيل أصلُه إلهٌ فحُذفت همزتُه، وأُدخل عليها الألفُ واللام، فخُصَّ بالباري تعالى","en":"Allah: its origin is said to be ilah, its hamza dropped and the definite article prefixed, so that it became proper to the Creator alone","ur":"اللہ: کہا گیا اِس کی اصل إلٰہ ہے، ہمزہ گرا اور الف لام داخل ہوا، پس یہ باری تعالیٰ کے ساتھ خاص ہو گیا"},"distinctive_note":{"ar":"يعرض الراغب أربعةَ اشتقاقاتٍ للاسم - العبادةُ، والتحيُّرُ، والوَلَهُ، والاحتجابُ - ولا يرجّح واحداً منها قطعاً","en":"al-Raghib lays out four derivations of the name - worship, bewilderment, yearning, and veiling - and does not decisively prefer one","ur":"الراغب اسم کے چار اشتقاق پیش کرتے ہیں — عبادت، تحیر، وَلَہ، احتجاب — اور کسی ایک کو قطعی ترجیح نہیں دیتے"},"authors_own_words":{"ar":"وأَلَهَ فلانٌ يَأْلُهُ إلاهةً: عَبَدَ، وقيل: تَأَلَّهَ؛ فالإلهُ على هذا هو المعبود","en":"and so-and-so alaha yaluhu ilahatan - he worshipped; and it is said taallaha. On this, al-ilah is the one worshipped","ur":"أَلَهَ فلانٌ یَأْلُهُ إلاہۃً: عبادت کی، اور کہا گیا تَأَلَّہَ؛ پس اِس بنا پر إلٰہ وہ ہے جس کی عبادت کی جائے"}},"poles":[{"key":"worship","label":{"ar":"العبادةُ والمعبود","en":"worship, and the one worshipped","ur":"عبادت اور معبود"}},{"key":"bewilderment","label":{"ar":"التحيُّرُ في الصفات","en":"bewilderment before the attributes","ur":"صفات میں تحیر"}}],"forms":[{"form_id":"mfr_alh_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:hamzated","madi":"أَلَهَ","mudari":"يَأْلُهُ","masdar_term":"GT:derivation_type:masdar","masadir":["إلاهة"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"worship","pole_family":"PF:alh_worship_bewilderment","trans":["GT:transitivity:transitive"],"trans_note":{"ar":"وقيل: تَأَلَّهَ؛ فالإلهُ على هذا هو المعبود","en":"and it is said taallaha; on this, al-ilah is the one worshipped","ur":"اور کہا گیا: تَأَلَّہَ؛ پس اِس بنا پر إلٰہ وہ ہے جس کی عبادت کی جائے"},"ayah":null,"gloss":{"ar":"أَلَهَ يَأْلُهُ إلاهةً: عَبَدَ","en":"alaha yaluhu ilahatan - he worshipped","ur":"أَلَهَ یَأْلُهُ إلاہۃً: اُس نے عبادت کی"},"senses":[{"sense":{"ar":"العبادة","en":"worshipping","ur":"عبادت کرنا"},"example":{"ar":"وأَلَهَ فلانٌ يَأْلُهُ الآلهةَ: عَبَدَ","en":"and so-and-so alaha - he worshipped the gods","ur":"أَلَهَ فلانٌ یَأْلُهُ الآلہۃَ: اُس نے معبودوں کی عبادت کی"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_alh_f2","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:hamzated","madi":"أَلِهَ","mudari":"يَأْلَهُ","masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"bewilderment","pole_family":"PF:alh_worship_bewilderment","trans":["GT:transitivity:intransitive"],"trans_note":null,"ayah":null,"gloss":{"ar":"وقيل: هو من أَلِهَ، أي: تحيَّر","en":"and it is said it is from aliha - that is, he was bewildered","ur":"اور کہا گیا: یہ أَلِهَ سے ہے، یعنی حیران ہوا"},"senses":[{"sense":{"ar":"التحيُّر","en":"bewilderment","ur":"حیرت"},"example":{"ar":"وذلك أنّ العبدَ إذا تفكَّر في صفاتِه تحيَّر فيها","en":"and that is because when the servant reflects on His attributes he is bewildered in them","ur":"کیونکہ بندہ جب اُس کی صفات میں غور کرے تو حیران رہ جاتا ہے"}}],"shahid":{"ar":"تفكَّروا في آلاءِ اللهِ ولا تفكَّروا في الله","en":"reflect upon God''s bounties, and do not reflect upon God","ur":"اللہ کی نعمتوں میں غور کرو، اللہ کی ذات میں غور نہ کرو"},"levels_with":[]},{"form_id":"mfr_alh_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hamzated","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"worship","pole_family":"PF:alh_worship_bewilderment","trans":[],"trans_note":{"ar":"وقيل: أصلُه وَلاهٌ، فأُبدل من الواو همزة، لكونِ كلِّ مخلوقٍ والهاً نحوه؛ وقيل: أصلُه من لاهَ يَلُوهُ لِياهاً، أي: احتجب","en":"and it is said its origin is walah, the waw replaced by hamza, since every creature yearns towards Him; and it is said its origin is from laha yaluhu liyahan - that is, He veiled Himself","ur":"اور کہا گیا: اِس کی اصل وَلاہ ہے، واو کی جگہ ہمزہ آیا، کیونکہ ہر مخلوق اُس کی طرف والہ ہے؛ اور کہا گیا: اصل لاهَ یَلُوهُ لِیاهاً سے ہے، یعنی چھپ گیا"},"ayah":"Maryam 19:65","gloss":{"ar":"اللهُ: اسمٌ خُصَّ بالباري تعالى، ولتخصُّصِه به لا سَمِيَّ له","en":"Allah: a name made proper to the Creator, and because it is proper to Him He has no namesake","ur":"اللہ: وہ نام جو باری تعالیٰ کے ساتھ خاص ہے، اور اِسی تخصیص کی بنا پر اُس کا کوئی ہم نام نہیں"},"senses":[{"sense":{"ar":"المخصوصُ بالباري لا سَمِيَّ له","en":"proper to the Creator, with no namesake","ur":"باری تعالیٰ کے ساتھ خاص، جس کا کوئی ہم نام نہیں"},"example":{"ar":"هَلْ تَعْلَمُ لَهُ سَمِيًّا","en":"do you know for Him any namesake","ur":"کیا تم اُس کا کوئی ہم نام جانتے ہو"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_alh_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hamzated","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"worship","pole_family":"PF:alh_worship_bewilderment","trans":[],"trans_note":{"ar":"وسمَّوا الشمسَ إلاهةً لاتّخاذِهم إيّاها معبوداً","en":"and they called the sun ilaha, because they took it as an object of worship","ur":"اور اُنہوں نے سورج کو إلاہۃ کہا کیونکہ اُسے معبود بنایا"},"ayah":"al-Anbiya 21:43; al-Araf 7:127","gloss":{"ar":"وإلهٌ حقُّه ألّا يُجمع، إذ لا معبودَ سواه، لكنّ العربَ لاعتقادِهم أنّ هاهنا معبوداتٍ جمعوه","en":"ilah by rights should not be pluralised, since there is no worshipped one but Him; but the Arabs pluralised it because they believed there were gods here","ur":"إلٰہ کا حق یہ تھا کہ جمع نہ ہو، کیونکہ اُس کے سوا کوئی معبود نہیں؛ مگر عرب نے اپنے اعتقاد کی بنا پر اِسے جمع کیا"},"senses":[{"sense":{"ar":"ما اتُّخذ معبوداً","en":"whatever is taken as an object of worship","ur":"جو معبود بنا لیا جائے"},"example":{"ar":"أَمْ لَهُمْ آلِهَةٌ تَمْنَعُهُمْ مِنْ دُونِنا","en":"or have they gods to defend them apart from Us","ur":"یا اُن کے ایسے معبود ہیں جو ہمارے مقابلے میں اُنہیں بچا لیں"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.82. The entry is TOC-less in the Shamela text, running inline after alam as \"alh\". Two Form I rows carry different babs because al-Raghib offers them as rival derivations of the divine name, not as one verb with two senses; the walah and laha derivations are carried as trans_notes since he reports them without a paradigm. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_hyy_fam', 'raghib_mufradat', 're_mfr_b1019c5dc3b3263a', 'حيي',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 268,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:lafif","block_meta":{"core":{"ar":"الحياةُ تُستعمل على أوجهٍ ستّة","en":"hayat is used in six ways","ur":"حیات چھ وجوہ پر استعمال ہوتی ہے"},"distinctive_note":{"ar":"يبني الراغب على السُّلَّم: القوّةُ الناميةُ، فالحاسّةُ، فالعاقلةُ، فارتفاعُ الغمّ، فالحياةُ الأخرويّة، فحياةُ الباري التي لا يصحّ عليها الموت","en":"al-Raghib builds a ladder: the growing faculty, then the sensing, then the reasoning, then the lifting of grief, then the life of the hereafter, then the life of the Creator upon which death is impossible","ur":"الراغب ایک سیڑھی بناتے ہیں: قوتِ نامیہ، پھر حاسّہ، پھر عاقلہ، پھر غم کا اٹھ جانا، پھر حیاتِ اخروی، پھر باری کی حیات جس پر موت روا نہیں"},"authors_own_words":{"ar":"والحياةُ الأخرويّةُ الأبديّة، وذلك يُتوصَّل إليه بالحياةِ التي هي العقلُ والعلم","en":"and the everlasting life of the hereafter - and it is reached by the life that is intellect and knowledge","ur":"اور حیاتِ اخرویِ ابدی، اور اُس تک اُس حیات سے پہنچا جاتا ہے جو عقل و علم ہے"}},"poles":[{"key":"life","label":{"ar":"الحياةُ بمراتبِها","en":"life in its degrees","ur":"حیات اپنے مراتب کے ساتھ"}},{"key":"modesty","label":{"ar":"الحياءُ: انقباضُ النفسِ عن القبائح","en":"haya: the soul drawing back from what is base","ur":"حیا: نفس کا قبائح سے سکڑ جانا"}},{"key":"greeting","label":{"ar":"التحيّةُ: الدعاءُ بالحياة","en":"tahiyya: the prayer for life","ur":"تحیت: حیات کی دعا"}}],"forms":[{"form_id":"mfr_hyy_f1","roman":"I","bab":"GT:form_family:bab_samia","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:lafif","madi":"حَيِيَ","mudari":"يَحْيَا","masdar_term":"GT:derivation_type:masdar","masadir":["حَياة"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"حَيّ","ism_maf_term":null,"ism_maf":null,"pole":"life","pole_family":"PF:hyy_life_modesty","trans":["GT:transitivity:intransitive"],"trans_note":null,"ayah":"al-Hadid 57:17; Fatir 35:22; al-Anam 6:122; Al Imran 3:169; al-Fajr 89:24","gloss":{"ar":"الحياةُ على ستّةِ أوجه","en":"hayat runs in six ways","ur":"حیات چھ وجوہ پر ہے"},"senses":[{"sense":{"ar":"القوّةُ الناميةُ في النباتِ والحيوان","en":"the growing faculty in plant and animal","ur":"نبات و حیوان میں قوتِ نامیہ"},"example":{"ar":"اعْلَمُوا أَنَّ اللَّهَ يُحْيِ الْأَرْضَ بَعْدَ مَوْتِها","en":"know that God revives the earth after its death","ur":"جان لو کہ اللہ زمین کو اُس کے مرنے کے بعد زندہ کرتا ہے"}},{"sense":{"ar":"القوّةُ الحسّاسة، وبه سُمّي الحيوانُ حيواناً","en":"the sensing faculty - and by it the animal is called hayawan","ur":"قوتِ حاسّہ، اور اسی سے حیوان حیوان کہلایا"},"example":{"ar":"وَما يَسْتَوِي الْأَحْياءُ وَلَا الْأَمْواتُ","en":"the living and the dead are not equal","ur":"اور زندے اور مردے برابر نہیں"}},{"sense":{"ar":"القوّةُ العاملةُ العاقلة","en":"the acting, reasoning faculty","ur":"قوتِ عاملہ عاقلہ"},"example":{"ar":"أَوَمَنْ كانَ مَيْتاً فَأَحْيَيْناهُ","en":"is one who was dead and We gave him life","ur":"کیا وہ جو مردہ تھا پھر ہم نے اُسے زندہ کیا"}},{"sense":{"ar":"ارتفاعُ الغمّ","en":"the lifting of grief","ur":"غم کا اٹھ جانا"},"example":{"ar":"وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْواتاً بَلْ أَحْياءٌ","en":"do not reckon those slain in God''s way to be dead - rather, living","ur":"اور جو اللہ کی راہ میں مارے گئے اُنہیں مردہ نہ سمجھو، بلکہ وہ زندہ ہیں"}},{"sense":{"ar":"الحياةُ الأخرويّةُ الأبديّة","en":"the everlasting life of the hereafter","ur":"حیاتِ اخرویِ ابدی"},"example":{"ar":"يا لَيْتَنِي قَدَّمْتُ لِحَياتِي","en":"would that I had sent ahead for my life","ur":"کاش میں نے اپنی زندگی کے لیے کچھ آگے بھیجا ہوتا"}},{"sense":{"ar":"الحياةُ التي يوصف بها الباري، ومعناها: لا يصحّ عليه الموت","en":"the life by which the Creator is described - meaning that death is impossible for Him","ur":"وہ حیات جس سے باری تعالیٰ موصوف ہیں، یعنی: اُن پر موت روا نہیں"},"example":{"ar":"إذا قيل فيه تعالى: هو حيٌّ، فمعناه: لا يصحّ عليه الموت، وليس ذلك إلّا لله","en":"when it is said of Him that He is living, it means death is impossible for Him - and that is for God alone","ur":"جب اُس کے بارے میں کہا جائے: وہ حی ہے، تو معنی یہ ہے کہ اُس پر موت روا نہیں، اور یہ صرف اللہ کے لیے ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_hyy_f2","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:lafif","madi":"أَحْيَا","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إحياء"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"مُحْيٍ","ism_maf_term":null,"ism_maf":null,"pole":"life","pole_family":"PF:hyy_life_modesty","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":"al-Baqara 2:258; al-Maida 5:32; al-Anfal 8:24; al-Baqara 2:260","gloss":{"ar":"الإحياءُ: جَعْلُ الشيءِ ذا حياة، ويقال في التنجيةِ من الهلاك","en":"ihya is making a thing alive, and is said also of rescuing from destruction","ur":"احیاء: کسی چیز کو زندہ کرنا، اور ہلاکت سے بچانے پر بھی بولا جاتا ہے"},"senses":[{"sense":{"ar":"الإحياءُ على الحقيقة","en":"giving life in truth","ur":"حقیقی احیاء"},"example":{"ar":"رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ","en":"my Lord is He who gives life and gives death","ur":"میرا رب وہ ہے جو زندہ کرتا ہے اور مارتا ہے"}},{"sense":{"ar":"التنجيةُ من الهلاك","en":"rescuing from destruction","ur":"ہلاکت سے بچانا"},"example":{"ar":"وَمَنْ أَحْياها فَكَأَنَّما أَحْيَا النَّاسَ جَمِيعاً، أي: مَن نجَّاها من الهلاك","en":"and whoever gives it life, it is as though he gave life to all people - that is, whoever rescued it from destruction","ur":"اور جس نے اُسے زندہ رکھا گویا اُس نے سب لوگوں کو زندہ رکھا، یعنی: جس نے اُسے ہلاکت سے بچایا"}},{"sense":{"ar":"العفوُ، فيكون إحياءً","en":"pardoning, which counts as giving life","ur":"معاف کر دینا، جو احیاء ہے"},"example":{"ar":"قالَ: أَنَا أُحْيِي وَأُمِيتُ، أي: أعفو فيكون إحياءً","en":"he said: I give life and give death - that is, I pardon, and that counts as giving life","ur":"اُس نے کہا: میں زندہ کرتا ہوں اور مارتا ہوں، یعنی: میں معاف کر دیتا ہوں سو یہ احیاء ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_hyy_f3","roman":"X","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_x","root_type":"GT:root_type:lafif","madi":"اسْتَحْيَا","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["استحياء"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"modesty","pole_family":"PF:hyy_life_modesty","trans":["GT:transitivity:transitive_by_harf"],"trans_note":{"ar":"وليس يُراد به في وصفِ الله انقباضُ النفس، إذ هو تعالى منزَّهٌ عن ذلك، وإنّما المرادُ تركُ القبائحِ وفعلُ المحاسن","en":"and in describing God the soul''s drawing back is not meant, for He is far above that; what is meant is the leaving of base things and the doing of good ones","ur":"اللہ کی صفت میں نفس کا سکڑنا مراد نہیں، وہ اِس سے منزہ ہے؛ مراد قبائح کا ترک اور محاسن کا فعل ہے"},"ayah":"al-Baqara 2:26; al-Ahzab 33:53; al-Baqara 2:49","gloss":{"ar":"الحياءُ: انقباضُ النفسِ عن القبائحِ وتركُها؛ والاستحياءُ في وجهٍ آخر: الاستبقاء","en":"haya is the soul''s drawing back from base things and leaving them; in another aspect istihya is sparing alive","ur":"حیا: نفس کا قبائح سے سکڑنا اور اُنہیں چھوڑنا؛ اور دوسرے رخ سے استحیاء: زندہ چھوڑ دینا"},"senses":[{"sense":{"ar":"انقباضُ النفسِ عن القبائح","en":"the soul drawing back from base things","ur":"نفس کا قبائح سے سکڑنا"},"example":{"ar":"إِنَّ اللَّهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا ما بَعُوضَةً فَما فَوْقَها","en":"God is not ashamed to strike a likeness, even of a gnat or what is above it","ur":"اللہ اِس سے نہیں شرماتا کہ مچھر یا اُس سے بڑھ کر کی مثال دے"}},{"sense":{"ar":"الاستبقاء","en":"sparing alive","ur":"زندہ چھوڑ دینا"},"example":{"ar":"وَيَسْتَحْيُونَ نِساءَكُمْ، أي: يستبقونهنّ","en":"and they spared your women - that is, they let them live","ur":"اور تمہاری عورتوں کو زندہ رکھتے تھے، یعنی: باقی رہنے دیتے تھے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_hyy_f4","roman":"II","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_ii","root_type":"GT:root_type:lafif","madi":"حَيَّا","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["تحيّة"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"greeting","pole_family":"PF:hyy_life_modesty","trans":["GT:transitivity:transitive"],"trans_note":{"ar":"وأصلُ التحيّةِ من الحياة، ثمّ جُعل ذلك دعاءَ تحيّةٍ لكونِ جميعِه غيرَ خارجٍ عن حصولِ الحياةِ أو سببِ حياة","en":"the origin of tahiyya is from life; it was then made a greeting-prayer since none of it falls outside the obtaining of life or a cause of life","ur":"تحیت کی اصل حیات سے ہے، پھر اِسے دعائے تحیت بنایا گیا کیونکہ اِس کا سارا حصہ حصولِ حیات یا سببِ حیات سے باہر نہیں"},"ayah":"al-Nisa 4:86; al-Nur 24:61","gloss":{"ar":"التحيّةُ: أن يقال: حيّاك الله، أي: جعل لك حياة، وذلك إخبارٌ ثمّ يُجعل دعاءً","en":"tahiyya is to say hayyaka llah - may God grant you life; a statement, then made into a prayer","ur":"تحیت: یہ کہنا کہ حَیَّاکَ اللہ، یعنی اللہ تجھے حیات دے؛ یہ خبر ہے پھر دعا بنا دی جاتی ہے"},"senses":[{"sense":{"ar":"الدعاءُ بالحياة","en":"the prayer for life","ur":"حیات کی دعا"},"example":{"ar":"وَإِذا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْها","en":"and when you are greeted with a greeting, greet with a better one","ur":"اور جب تمہیں سلام کیا جائے تو اُس سے بہتر سلام کرو"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_hyy_f5","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:lafif","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"life","pole_family":"PF:hyy_life_modesty","trans":[],"trans_note":{"ar":"والحَيَا: المطر، لأنه يُحيي الأرضَ بعد موتِها","en":"and al-haya is rain, because it revives the earth after its death","ur":"اور الحَیا: بارش، کیونکہ وہ زمین کو اُس کے مرنے کے بعد زندہ کرتی ہے"},"ayah":"al-Ankabut 29:64; al-Anbiya 21:30","gloss":{"ar":"الحَيَوانُ: مَقَرُّ الحياة، ويقال على ضربين","en":"al-hayawan is the seat of life, and is said in two ways","ur":"الحیوان: حیات کا ٹھکانا، اور یہ دو طرح بولا جاتا ہے"},"senses":[{"sense":{"ar":"ما له الحاسّة، وما له البقاءُ الأبديّ","en":"that which has sensation, and that which has everlasting subsistence","ur":"وہ جس میں حس ہو، اور وہ جسے بقائے ابدی حاصل ہو"},"example":{"ar":"وَإِنَّ الدَّارَ الْآخِرَةَ لَهِيَ الْحَيَوانُ لَوْ كانُوا يَعْلَمُونَ","en":"and the abode of the hereafter, that is life indeed, if only they knew","ur":"اور بےشک آخرت کا گھر ہی اصل زندگی ہے، کاش وہ جانتے"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.268. The six senses under the Form I row are al-Raghib''s own enumerated list (al-ula, al-thaniya ... al-sadisa), which is why they sit as senses under one row rather than as six separate forms. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_mwt_fam', 'raghib_mufradat', 're_mfr_335da23c98d6d7e8', 'موت',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 781,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:hollow_w","block_meta":{"core":{"ar":"أنواعُ الموتِ بحسبِ أنواعِ الحياة","en":"the kinds of death follow the kinds of life","ur":"موت کی اقسام حیات کی اقسام کے مطابق ہیں"},"distinctive_note":{"ar":"يبني الراغب مدخلَ الموتِ مرآةً لمدخلِ الحياة، فيقابل كلَّ مرتبةٍ من الحياةِ بموتٍ يخصّها، ويُدرج النومَ خامساً","en":"al-Raghib builds the death entry as a mirror of the life entry, matching each degree of life with a death proper to it, and enters sleep as the fifth","ur":"الراغب مدخلِ موت کو مدخلِ حیات کا آئینہ بناتے ہیں، ہر مرتبۂ حیات کے مقابل ایک موت رکھتے ہیں، اور نیند کو پانچویں میں شمار کرتے ہیں"},"authors_own_words":{"ar":"الخامس: المنامُ، فقيل: النومُ موتٌ خفيف، والموتُ نومٌ ثقيل، وعلى هذا النحوِ سمّاهما اللهُ تعالى توفِّياً","en":"the fifth is sleep; it is said sleep is a light death and death a heavy sleep - and it is on this pattern that God has called them both a taking-in-full","ur":"پانچویں: نیند؛ کہا گیا نیند ہلکی موت ہے اور موت گہری نیند، اور اسی بنا پر اللہ نے دونوں کو توفی کہا"}},"poles":[{"key":"death","label":{"ar":"زوالُ القوّةِ الحيوانيّةِ وإبانةُ الروحِ عن الجسد","en":"the passing of the animal faculty and the parting of spirit from body","ur":"قوتِ حیوانی کا زوال اور روح کا بدن سے جدا ہونا"}},{"key":"ignorance","label":{"ar":"زوالُ القوّةِ العاقلة، وهي الجهالة","en":"the passing of the reasoning faculty - that is, ignorance","ur":"قوتِ عاقلہ کا زوال، یعنی جہالت"}},{"key":"sorrow","label":{"ar":"الحزنُ المكدِّرُ للحياة","en":"the grief that troubles life","ur":"وہ غم جو زندگی کو مکدر کرے"}},{"key":"sleep","label":{"ar":"المنامُ: موتٌ خفيف","en":"sleep: a light death","ur":"نیند: ہلکی موت"}}],"forms":[{"form_id":"mfr_mwt_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:hollow_w","madi":"ماتَ","mudari":"يَمُوتُ","masdar_term":"GT:derivation_type:masdar","masadir":["مَوْت"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"مَيِّت","ism_maf_term":null,"ism_maf":null,"pole":"death","pole_family":"PF:mwt_death_privation","trans":["GT:transitivity:intransitive"],"trans_note":{"ar":"وقد فَصَلَ قومٌ بين المَيِّتِ والمائت، فقالوا: المائتُ هو المتحلِّل؛ قال القاضي عليُّ بن عبد العزيز: ليس في لغتِنا مائتٌ على حسبِ ما قالوه","en":"some have distinguished mayyit from mait, saying the mait is the one dissolving away; al-Qadi Ali b. Abd al-Aziz said: there is no mait in our language in the way they claim","ur":"بعض نے مَیِّت اور مائت میں فرق کیا: مائت وہ ہے جو تحلیل ہو رہا ہو؛ قاضی علی بن عبد العزیز نے کہا: ہماری زبان میں اُن کے دعوے کے مطابق مائت نہیں"},"ayah":"Al Imran 3:185; Maryam 19:23; al-Anam 6:122; Ibrahim 14:17; al-Zumar 39:42","gloss":{"ar":"أنواعُ الموتِ بحسبِ أنواعِ الحياة","en":"the kinds of death follow the kinds of life","ur":"موت کی اقسام حیات کی اقسام کے مطابق"},"senses":[{"sense":{"ar":"ما هو بإزاءِ القوّةِ النامية","en":"that which answers to the growing faculty","ur":"وہ جو قوتِ نامیہ کے مقابل ہے"},"example":{"ar":"يُحْيِ الْأَرْضَ بَعْدَ مَوْتِها","en":"He revives the earth after its death","ur":"وہ زمین کو اُس کے مرنے کے بعد زندہ کرتا ہے"}},{"sense":{"ar":"زوالُ القوّةِ الحاسّة","en":"the passing of the sensing faculty","ur":"قوتِ حاسّہ کا زوال"},"example":{"ar":"يا لَيْتَنِي مِتُّ قَبْلَ هذا","en":"would that I had died before this","ur":"کاش میں اِس سے پہلے مر جاتی"}},{"sense":{"ar":"زوالُ القوّةِ العاقلة، وهي الجهالة","en":"the passing of the reasoning faculty - that is, ignorance","ur":"قوتِ عاقلہ کا زوال، یعنی جہالت"},"example":{"ar":"أَوَمَنْ كانَ مَيْتاً فَأَحْيَيْناهُ","en":"is one who was dead and We gave him life","ur":"کیا وہ جو مردہ تھا پھر ہم نے اُسے زندہ کیا"}},{"sense":{"ar":"الحزنُ المكدِّرُ للحياة","en":"the grief that troubles life","ur":"وہ غم جو زندگی کو مکدر کرے"},"example":{"ar":"وَيَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكانٍ وَما هُوَ بِمَيِّتٍ","en":"and death comes at him from every side, yet he does not die","ur":"اور موت اُس پر ہر طرف سے آتی ہے مگر وہ مرتا نہیں"}},{"sense":{"ar":"المنامُ، فالنومُ موتٌ خفيف والموتُ نومٌ ثقيل","en":"sleep - for sleep is a light death and death a heavy sleep","ur":"نیند، سو نیند ہلکی موت ہے اور موت گہری نیند"},"example":{"ar":"اللَّهُ يَتَوَفَّى الْأَنْفُسَ حِينَ مَوْتِها وَالَّتِي لَمْ تَمُتْ فِي مَنامِها","en":"God takes the souls at their death, and those that have not died, in their sleep","ur":"اللہ جانوں کو اُن کی موت کے وقت قبض کرتا ہے، اور جو نہیں مریں اُنہیں نیند میں"}}],"shahid":{"ar":"كُلُّ نَفْسٍ ذائِقَةُ الْمَوْتِ","en":"every soul shall taste death","ur":"ہر جان موت کا مزہ چکھنے والی ہے"},"levels_with":[]},{"form_id":"mfr_mwt_f2","roman":"IV","bab":null,"bab_alt":[],"form_tier":"GT:form_family:form_iv","root_type":"GT:root_type:hollow_w","madi":"أَماتَ","mudari":null,"masdar_term":"GT:derivation_type:masdar","masadir":["إماتة"],"ism_fail_term":"GT:derivation_type:active_participle","ism_fail":"مُميت","ism_maf_term":null,"ism_maf":null,"pole":"death","pole_family":"PF:mwt_death_privation","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":null,"gloss":{"ar":"إماتةُ الخمرِ: كنايةٌ عن طَبْخِها","en":"the imata of wine is a way of saying its cooking","ur":"شراب کی إماتۃ: اُس کے پکانے سے کنایہ"},"senses":[{"sense":{"ar":"إذهابُ الحياة","en":"taking life away","ur":"حیات کا ختم کرنا"},"example":{"ar":"وناقةٌ مُميتةٌ ومُميتٌ: ماتَ ولدُها","en":"a mumita or mumit she-camel: her young one has died","ur":"ناقۂ مُمیتہ و مُمیت: جس کا بچہ مر گیا"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_mwt_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hollow_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"death","pole_family":"PF:mwt_death_privation","trans":[],"trans_note":{"ar":"والمَيْتُ مخفَّفٌ عن المَيِّت، ويقال: بَلَدٌ مَيِّتٌ ومَيْتٌ","en":"mayt is a lightened form of mayyit; and one says baladun mayyitun and mayt","ur":"مَیْت، مَیِّت کی تخفیف ہے؛ اور کہا جاتا ہے: بَلَدٌ مَیِّتٌ اور مَیْتٌ"},"ayah":"al-Maida 5:3; al-Anam 6:145; Fatir 35:9","gloss":{"ar":"المَيْتةُ من الحيوان: ما زال روحُه بغيرِ تذكية","en":"the mayta of an animal: one whose spirit has departed without ritual slaughter","ur":"حیوان کی میتہ: جس کی روح بغیر تذکیہ کے نکل گئی"},"senses":[{"sense":{"ar":"ما زال روحُه بغيرِ تذكية","en":"that whose spirit departed without ritual slaughter","ur":"جس کی روح بغیر ذبح کے نکلی"},"example":{"ar":"حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ","en":"carrion has been forbidden you","ur":"تم پر مردار حرام کیا گیا"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_mwt_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hollow_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"ignorance","pole_family":"PF:mwt_death_privation","trans":[],"trans_note":{"ar":"ومنه: رجلٌ مَوْتانُ القلب، وامرأةٌ مَوْتانةٌ؛ والمَوَتانُ بإزاءِ الحيوان، وهي الأرضُ التي لم تَحْيَ للزَّرع","en":"and from it: a man mawtan of heart, a woman mawtana; and al-mawatan stands over against the animate - it is land that has not come alive for sowing","ur":"اور اِسی سے: رجلٌ مَوْتانُ القلب، امرأۃٌ مَوْتانۃ؛ اور المَوَتان حیوان کے مقابل ہے، یعنی وہ زمین جو کھیتی کے لیے زندہ نہ ہوئی"},"ayah":null,"gloss":{"ar":"المَوْتةُ: شِبْهُ الجنون، كأنّه من موتِ العلمِ والعقل","en":"al-mawta is something like madness, as though from the death of knowledge and reason","ur":"المَوْتۃ: جنون کی مانند، گویا علم و عقل کی موت سے"},"senses":[],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.781. Deliberately built as the mirror of the hyy block: the five senses of the Form I row answer one-for-one to the degrees of life al-Raghib sets out under hayat, which is his own arrangement, not an editorial pairing. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
  (id, source_slug, root_entry_id, root_norm, block_path, block_seq,
   depth, block_type, lang, title_en, printed_page, origin, data_json)
VALUES ('blk_mfr_abw_fam', 'raghib_mufradat', 're_mfr_5854fc9ada858ec6', 'ابو',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 57,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:defective_w","block_meta":{"core":{"ar":"الأبُ: الوالد، ويُسمَّى كلُّ من كان سبباً في إيجادِ شيءٍ أو صلاحِه أو ظهورِه أباً","en":"al-ab is the begetter; and anyone who is a cause of a thing''s coming to be, or its wellbeing, or its appearing, is called its father","ur":"الأب: والد، اور ہر وہ جو کسی چیز کے وجود، صلاح یا ظہور کا سبب ہو، اُسے أب کہا جاتا ہے"},"distinctive_note":{"ar":"يوسّع الراغب الأبوّةَ من الولادةِ إلى كلِّ سببيّة، فيدخل فيها المعلِّمُ والعمُّ والجدُّ، ويقرأ ﴿وَجَدْنا آباءَنا عَلى أُمَّةٍ﴾ على العلماءِ الذين ربَّوهم بالعلم","en":"al-Raghib widens fatherhood from begetting to any causation, taking in the teacher, the uncle and the grandfather, and reads \"we found our fathers upon a way\" as the scholars who raised them by knowledge","ur":"الراغب ابوت کو ولادت سے ہر سببیت تک وسیع کرتے ہیں، اُس میں معلم، چچا اور دادا داخل ہیں، اور ﴿وَجَدْنا آباءَنا عَلى أُمَّةٍ﴾ کو اُن علماء پر محمول کرتے ہیں جنہوں نے علم سے تربیت کی"},"authors_own_words":{"ar":"وسُمّي معلِّمُ الإنسانِ أباً لِما تقدَّم ذكرُه","en":"and a person''s teacher is called his father, for the reason already given","ur":"اور انسان کے معلم کو أب کہا گیا، اُسی وجہ سے جو پہلے گزری"}},"poles":[{"key":"fatherhood","label":{"ar":"الوالدُ على الحقيقة","en":"the begetter, properly so called","ur":"حقیقی والد"}},{"key":"causation","label":{"ar":"كلُّ سببٍ في إيجادِ شيءٍ أو صلاحِه","en":"any cause of a thing''s being or wellbeing","ur":"کسی چیز کے وجود یا صلاح کا ہر سبب"}},{"key":"tending","label":{"ar":"التفقُّدُ تفقُّدَ الأب","en":"looking after as a father looks after","ur":"باپ کی طرح خبر گیری"}}],"forms":[{"form_id":"mfr_abw_f1","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:defective_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"fatherhood","pole_family":"PF:abw_fatherhood_causation","trans":[],"trans_note":{"ar":"وأصلُ «أبٍ» فَعَلٌ، وقد أُجري مجرى قفا وعصا؛ وزادوا في النداءِ فيه تاءً، فقالوا: يا أَبَتِ","en":"the origin of ab is faal, and it has been made to run like qafa and asa; in the vocative they added a ta, saying ya abati","ur":"أب کی اصل فَعَل ہے، اور اِسے قفا و عصا کے مجریٰ پر چلایا گیا؛ اور نداء میں تاء بڑھا کر یا أبتِ کہا"},"ayah":"al-Ahzab 33:6; al-Ahzab 33:40; al-Baqara 2:133; al-Zukhruf 43:22","gloss":{"ar":"الأبُ: الوالد، وجمعُه آباءٌ وأُبوَّةٌ نحو: بُعولةٍ وخُؤولة","en":"al-ab is the begetter; its plurals are aba and ubuwwa, like buula and khuula","ur":"الأب: والد، جمع آباء اور أُبوّۃ، جیسے بُعولۃ اور خُؤولۃ"},"senses":[{"sense":{"ar":"الوالدُ على الحقيقة","en":"the begetter properly","ur":"حقیقی والد"},"example":{"ar":"ما كانَ مُحَمَّدٌ أَبا أَحَدٍ مِنْ رِجالِكُمْ — إنّما هو نفيُ الولادة","en":"Muhammad is not the father of any of your men - this is a denial of begetting only","ur":"محمد تمہارے مردوں میں سے کسی کے باپ نہیں — یہ محض ولادت کی نفی ہے"}},{"sense":{"ar":"كلُّ سببٍ في إيجادِ شيءٍ أو صلاحِه أو ظهورِه","en":"any cause of a thing''s coming to be, its wellbeing, or its appearing","ur":"کسی چیز کے وجود، صلاح یا ظہور کا ہر سبب"},"example":{"ar":"ولذلك يُسمَّى النبيُّ ﷺ أبا المؤمنين","en":"and for this the Prophet is called the father of the believers","ur":"اسی لیے نبی ﷺ کو مومنوں کا باپ کہا جاتا ہے"}},{"sense":{"ar":"العمُّ والجدُّ مع الأبِ يُسمَّيان أبوين","en":"the uncle and the grandfather, taken with the father, are called abawan","ur":"چچا اور دادا باپ کے ساتھ أبوین کہلاتے ہیں"},"example":{"ar":"نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ — وإسماعيلُ لم يكن من آبائهم وإنّما كان عمَّهم","en":"we worship your God and the God of your fathers Abraham, Ishmael and Isaac - yet Ishmael was not of their fathers but their uncle","ur":"ہم تیرے معبود اور تیرے آباء ابراہیم و اسماعیل و اسحاق کے معبود کی عبادت کریں گے — حالانکہ اسماعیل اُن کے آباء میں سے نہ تھے بلکہ چچا تھے"}},{"sense":{"ar":"المعلِّم","en":"the teacher","ur":"معلم"},"example":{"ar":"وَجَدْنا آباءَنا عَلى أُمَّةٍ، أي: علماءَنا الذين ربَّونا بالعلم","en":"we found our fathers upon a way - that is, our scholars, who raised us by knowledge","ur":"ہم نے اپنے آباء کو ایک طریقے پر پایا، یعنی: اپنے علماء کو جنہوں نے علم سے ہماری تربیت کی"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_abw_f2","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:defective_w","madi":"أَبا","mudari":"يَأْبُو","masdar_term":"GT:derivation_type:masdar","masadir":["أُبوَّة"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"tending","pole_family":"PF:abw_fatherhood_causation","trans":["GT:transitivity:transitive"],"trans_note":null,"ayah":null,"gloss":{"ar":"أبوتُ القومَ: كنتُ لهم أباً","en":"abawtu the people - I was a father to them","ur":"أبوتُ القوم: میں اُن کا باپ بنا"},"senses":[{"sense":{"ar":"القيامُ على الشيءِ تفقُّدَ الأب","en":"standing over a thing with a father''s care","ur":"باپ کی خبر گیری کے ساتھ کسی چیز کی نگہداشت"},"example":{"ar":"فلانٌ يَأْبُو بَهْمَهُ، أي: يتفقَّدُها تفقُّدَ الأب","en":"so-and-so yabu his lambs - that is, he looks after them as a father does","ur":"فلاں اپنے بھیڑ کے بچوں کی خبر گیری کرتا ہے، یعنی: باپ کی طرح"}}],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"p.57. Printed under the heading \"aba\", not \"ab\" - the neighbouring \"ab\" entry on p.59 is a different word entirely (abb, pasture, of Abasa 80:31) and must not be conflated with this one. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
INSERT INTO ar_ling_lexicon_block
