VALUES ('blk_mfr_awl_fam', 'raghib_mufradat', 're_mfr_8c529bf3e1a02ca0', 'اول',
        'e1.fam', 2, 1, 'sarf_family', 'ar', 'Sarf family', 100,
        'derived_display', '{"scope":"book","root_type":"GT:root_type:hollow_w","block_meta":{"core":{"ar":"التأويلُ من الأَوْل، أي: الرجوعُ إلى الأصل","en":"tawil is from awl - that is, the returning to the origin","ur":"تاویل الأَوْل سے ہے، یعنی اصل کی طرف رجوع"},"distinctive_note":{"ar":"ينقل الراغب عن الخليلِ نزاعاً في تأسيسِ «أوّل»: أمن همزةٍ وواوٍ ولامٍ فيكون فَعَّل، أم من واوين ولامٍ فيكون أفعل؟ ويرجّح الأوّل","en":"al-Raghib reports from al-Khalil a dispute over the root of awwal: is it from hamza, waw and lam, so that it is faal, or from two waws and a lam, so that it is afal? He prefers the first","ur":"الراغب خلیل سے «أوّل» کی تاسیس میں اختلاف نقل کرتے ہیں: ہمزہ، واو، لام سے ہے تو فَعَّل، یا دو واو اور لام سے تو أفعل؟ اور پہلے کو ترجیح دیتے ہیں"},"authors_own_words":{"ar":"قال الخليل: تأسيسُه من همزةٍ وواوٍ ولام، فيكون فَعَّل، وقد قيل: من واوين ولام، فيكون أفعل، والأوّلُ أفصحُ لقلّةِ وجودِ ما فاؤه وعينُه حرفٌ واحد","en":"al-Khalil said: its base is from hamza, waw and lam, so it is faal; and it has been said from two waws and a lam, so it is afal - and the first is the more eloquent, since words whose first and second radicals are the same letter are rare","ur":"خلیل نے کہا: اِس کی تاسیس ہمزہ، واو اور لام سے ہے تو یہ فَعَّل ہے؛ اور کہا گیا دو واو اور لام سے تو أفعل؛ اور پہلا افصح ہے کیونکہ جن کا فاء اور عین ایک ہی حرف ہو وہ کم ہیں"}},"poles":[{"key":"return","label":{"ar":"الرجوعُ إلى الأصلِ والغايةِ المرادة","en":"returning to the origin and to the intended end","ur":"اصل اور مطلوبہ غایت کی طرف رجوع"}},{"key":"priority","label":{"ar":"التقدُّمُ الذي يترتَّب عليه غيرُه","en":"the priority upon which another follows","ur":"وہ تقدم جس پر دوسرا مرتب ہو"}},{"key":"governance","label":{"ar":"السياسةُ التي تراعي مآلَها","en":"governing with an eye to where it will end","ur":"وہ سیاست جو اپنے انجام کا لحاظ رکھے"}}],"forms":[{"form_id":"mfr_awl_f1","roman":"I","bab":"GT:form_family:bab_nasara","bab_alt":[],"form_tier":null,"root_type":"GT:root_type:hollow_w","madi":"آلَ","mudari":"يَؤُولُ","masdar_term":"GT:derivation_type:masdar","masadir":["مَآل"],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"return","pole_family":"PF:awl_return_priority","trans":["GT:transitivity:transitive_by_harf"],"trans_note":null,"ayah":null,"gloss":{"ar":"آلَ يَؤُولُ: رجع","en":"ala yaulu - it returned","ur":"آلَ یَؤُولُ: لوٹ گیا"},"senses":[{"sense":{"ar":"الرجوع","en":"returning","ur":"رجوع"},"example":{"ar":"وآلَ اللبنُ يَؤُولُ: إذا خَثُرَ، كأنّه رجوعٌ إلى نقصان","en":"and the milk ala - when it thickened, as though a returning towards diminution","ur":"اور دودھ آلَ ہوا: جب گاڑھا ہو گیا، گویا نقصان کی طرف لوٹنا"}}],"shahid":{"ar":"والآلُ أيضاً: الحالُ التي يؤولُ إليها أمرُه","en":"and al-al is also the state to which a man''s affair returns","ur":"اور الآل: وہ حال جس کی طرف اُس کا معاملہ لوٹتا ہے"},"levels_with":[]},{"form_id":"mfr_awl_f2","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hollow_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"return","pole_family":"PF:awl_return_priority","trans":[],"trans_note":{"ar":"ومنه: المَوْئِلُ، للموضعِ الذي يُرجَع إليه","en":"and from it al-mawil, for the place to which one returns","ur":"اور اسی سے: المَوْئِل، وہ جگہ جس کی طرف لوٹا جائے"},"ayah":"Al Imran 3:7; al-Araf 7:53; al-Nisa 4:59","gloss":{"ar":"التأويلُ: ردُّ الشيءِ إلى الغايةِ المرادةِ منه، علماً كان أو فعلاً","en":"tawil is the bringing back of a thing to the end intended of it, whether in knowing or in doing","ur":"تاویل: کسی چیز کو اُس کی مطلوبہ غایت کی طرف لوٹانا، خواہ علم میں ہو یا فعل میں"},"senses":[{"sense":{"ar":"في العلم","en":"in knowing","ur":"علم میں"},"example":{"ar":"وَما يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ وَالرَّاسِخُونَ فِي الْعِلْمِ","en":"none knows its interpretation but God and those firmly rooted in knowledge","ur":"اور اُس کی تاویل کو اللہ اور علم میں پختہ لوگوں کے سوا کوئی نہیں جانتا"}},{"sense":{"ar":"في الفعل","en":"in doing","ur":"فعل میں"},"example":{"ar":"هَلْ يَنْظُرُونَ إِلَّا تَأْوِيلَهُ يَوْمَ يَأْتِي تَأْوِيلُهُ، أي: بيانُه الذي غايتُه المقصودةُ منه","en":"do they await anything but its outcome? On the day its outcome comes - that is, the disclosure that is its intended end","ur":"کیا وہ اُس کی تاویل ہی کے منتظر ہیں؟ جس دن اُس کی تاویل آئے گی، یعنی: وہ بیان جو اُس کی مقصود غایت ہے"}}],"shahid":null,"levels_with":[]},{"form_id":"mfr_awl_f3","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hollow_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"priority","pole_family":"PF:awl_return_priority","trans":[],"trans_note":{"ar":"وإذا قيل في صفةِ الله: هو الأوّل، فمعناه: أنّه الذي لم يسبقْه في الوجودِ شيء","en":"and when it is said of God that He is the First, it means that nothing preceded Him in existence","ur":"اور جب اللہ کی صفت میں کہا جائے: وہ اوّل ہے، تو معنی یہ ہے کہ وجود میں اُس سے پہلے کوئی چیز نہیں"},"ayah":"al-Anam 6:163; al-Araf 7:143; al-Baqara 2:41","gloss":{"ar":"فالأوّلُ: هو الذي يترتَّب عليه غيرُه، ويُستعمل على أربعةِ أوجه","en":"al-awwal is that upon which another follows, and it is used in four ways","ur":"فالأوّل: وہ جس پر دوسرا مرتب ہو، اور یہ چار وجوہ پر استعمال ہوتا ہے"},"senses":[{"sense":{"ar":"المتقدِّمُ بالزمان","en":"prior in time","ur":"زمانے میں مقدم"},"example":{"ar":"عبدُ الملكِ أوّلاً ثمّ المنصور","en":"Abd al-Malik first, then al-Mansur","ur":"پہلے عبد الملک، پھر منصور"}},{"sense":{"ar":"المتقدِّمُ بالرئاسة، وكونُ غيرِه محتذياً به","en":"prior in leadership, others taking their pattern from him","ur":"ریاست میں مقدم، اور دوسرے اُس کی پیروی کریں"},"example":{"ar":"الأميرُ أوّلاً ثمّ الوزير","en":"the commander first, then the minister","ur":"پہلے امیر، پھر وزیر"}},{"sense":{"ar":"المتقدِّمُ بالوضعِ والنسبة","en":"prior by position and relation","ur":"وضع اور نسبت میں مقدم"},"example":{"ar":"تقول للخارجِ من العراق: القادسيّةُ أوّلاً ثمّ فَيْد، وللخارجِ من مكّة: فَيْدٌ أوّلاً ثمّ القادسيّة","en":"to one leaving Iraq you say: al-Qadisiyya first, then Fayd; to one leaving Mecca: Fayd first, then al-Qadisiyya","ur":"عراق سے نکلنے والے سے کہو: پہلے قادسیہ پھر فَیْد؛ اور مکہ سے نکلنے والے سے: پہلے فَیْد پھر قادسیہ"}},{"sense":{"ar":"المتقدِّمُ بالنظامِ الصناعيّ","en":"prior in the order of making","ur":"صناعی نظام میں مقدم"},"example":{"ar":"الأساسُ أوّلاً ثمّ البناء","en":"the foundation first, then the building","ur":"پہلے بنیاد، پھر عمارت"}}],"shahid":{"ar":"وَأَنَا أَوَّلُ الْمُسْلِمِينَ — أي: أنا المقتدى بي في الإسلام","en":"and I am the first of those who submit - that is, I am the one taken as a pattern in submission","ur":"اور میں سب سے پہلا مسلم ہوں — یعنی: اسلام میں میری اقتدا کی جاتی ہے"},"levels_with":[]},{"form_id":"mfr_awl_f4","roman":"—","bab":null,"bab_alt":[],"form_tier":"GT:form_family:noun_derivatives","root_type":"GT:root_type:hollow_w","madi":null,"mudari":null,"masdar_term":null,"masadir":[],"ism_fail_term":null,"ism_fail":null,"ism_maf_term":null,"ism_maf":null,"pole":"governance","pole_family":"PF:awl_return_priority","trans":[],"trans_note":{"ar":"يقال: أُلْنا وإِيلَ علينا","en":"one says: ulna, and ila alayna - we governed, and we were governed","ur":"کہا جاتا ہے: أُلْنا وإِيلَ علينا"},"ayah":null,"gloss":{"ar":"والأَوْلُ: السياسةُ التي تراعي مآلَها","en":"and al-awl is the governing that keeps an eye on where it will end","ur":"اور الأَوْل: وہ سیاست جو اپنے مآل کا لحاظ رکھے"},"senses":[],"shahid":null,"levels_with":[]}],"levelling_groups":[],"nominals":[],"defect_note":null,"register":"labels bound to ar_ling_gram_term via full GT:category:term id","note":"pp.99-101. The material has no TOC heading of its own: it runs inside the \"al\" article, which is why a heading-only pass missed it. The homonym al (family), which al-Raghib calls maqlub of ahl, is a different word and is deliberately NOT modelled in this block. family as al-Raghib presents it in al-Mufradat fi gharib al-Quran; text read from the Shamela digitisation (book 6119) held locally. Book-scope economy: only representative shawahid kept, the full citation catalogue belongs in passage-level footnotes."}');
